insert into public.items (kind, slug, title, tag, category_label, tune, blocks, sort_order)
values
  ('active', 'fall-in', 'Fall In', 'hall', 'Warm-up · Cubs', 'Whole pack · hall or field', '[{"type":"verse","text":"A quick way to bring a noisy pack to a stop. The Cubs line up in an order you call, then have to rebuild the line somewhere new the moment you clap."},{"type":"steps","heading":"How to play","items":["Ask the Cubs to line up in front of you, for example by height, and wait until they are still and quiet.","Walk quietly to a new spot at the other side of the space and clap once.","Everyone hurries to re-form the same line where you now stand.","Next round, call a new order, such as birthdays, and clap from a new place.","For a harder round, ban talking altogether."]},{"type":"box","heading":"Variations","items":["Time each round and try to beat the last time.","Let a Sixer pick the order and the new spot."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 1),
  ('active', 'escaped-prisoner', 'Escaped Prisoner', 'anywhere', 'Circle · Cubs', '8 or more · hall or field', '[{"type":"verse","text":"One Cub is trapped inside a ring of linked hands and tries to escape without breaking through."},{"type":"steps","heading":"How to play","items":["The pack stands in a tight circle holding hands. One Cub stands inside as the prisoner.","The prisoner tries to get out by going over or under the linked arms. Breaking a grip is not allowed.","Once the prisoner is out, everyone else chases. The Cub who tags them becomes the next prisoner.","The ring joins hands again and the next round starts."]},{"type":"safety","heading":"Safety","items":["The ring lifts and lowers arms gently. Nobody pulls or twists."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 2),
  ('active', 'tin-can-bowling', 'Tin Can Bowling', 'hall', 'Team game · Cubs', 'Two teams · hall', '[{"type":"verse","text":"Two teams slide flying discs along the floor to knock down each other''s cans."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Aluminium drink can per Cub, empty"},{"qty":4,"item":"Flying discs (frisbees)"}]},{"type":"safety","heading":"Safety","items":["Discs are slid along the floor, never thrown.","Fingers and knees can get hit. Cubs who are out stay alert and keep their feet and hands clear."]},{"type":"steps","heading":"How to play","items":["Split the pack into two teams that sit on the floor facing each other, about 6 m apart. Each Cub stands a can on the floor in front of them.","Give each team two discs.","A Cub rests a hand on top of a disc and slides it across the floor at a can on the other team''s side.","You may not block an incoming disc. Touch it only after it has passed or missed your can.","When a can falls, that Cub is out and cannot stand it up again.","The first team to knock down all the other team''s cans wins. Reset and play again."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 3),
  ('active', 'skunk-tag-balance', 'Skunk Tag (balance)', 'anywhere', 'Tag · Cubs', 'Any number · hall or field', '[{"type":"verse","text":"A tag game where holding an awkward pose keeps you safe, but only as long as you can hold it."},{"type":"steps","heading":"How to play","items":["One Cub is \"it\". Everyone else stands on one leg, holds the other foot with one hand, and holds their nose with the other hand. In this pose they are safe.","If a safe Cub lets go of the foot or nose, or puts the second foot down, they can be tagged.","A tagged Cub becomes \"it\"."]},{"type":"note","text":"This is not the same as the hoop game also called Skunk Tag. See \"Skunk Tag (hoops)\"."},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 4),
  ('active', 'sock-wrestling', 'Sock Wrestling', 'hall', 'Contact game · Cubs', 'Pairs · hall with mats', '[{"type":"verse","text":"Two Cubs, one loose sock each, and a rule that you can only win by pulling the other Cub''s sock off."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Loose clean socks"},{"qty":2,"item":"or 3 × Mattresses or mats, side by side"}]},{"type":"safety","heading":"Safety","items":["Check the area is clear of anything hard. Match Cubs of a similar size.","Stop the match straight away if anyone is hurt or too rough."]},{"type":"steps","heading":"How to play","items":["Shoes and socks off. Two Cubs each put a loose sock on one foot.","Cubs wrestle on the mats and try to pull off the other''s sock using their hands.","Neither Cub may hold their own sock or pull it up with their hands.","If either goes off the mats, pause until they are back on.","Winner stays on or plays the next Cub."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 5),
  ('active', 'ice-hockey', 'Ice Hockey', 'hall', 'Team game · Cubs', 'Two teams · hall', '[{"type":"verse","text":"Hockey played with rolled newspaper bats and a block of ice for a puck."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Rolled, taped newspaper bat per player"},{"qty":null,"item":"Blocks of ice in small containers, as pucks"},{"qty":2,"item":"Chairs, as goals"}]},{"type":"safety","heading":"Safety","items":["Wipe up meltwater straight away. Play in socks or bare feet only if the floor is not slippery."]},{"type":"steps","heading":"How to play","items":["Make two teams who line up along opposite sides of the hall. Number the Cubs on each team.","Call a number. The two Cubs with that number run out, grab bats and play one-on-one.","They try to push the ice through or under their goal chair.","Call another number when a goal is scored and keep going."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 6),
  ('active', 'captains-coming', 'Captain''s Coming', 'hall', 'Listening · Cubs and Scouts', 'Whole pack · hall or field', '[{"type":"verse","text":"A listening game of sea commands. Everybody runs to the right spot or mimes the right action, and the last or slowest can be out in a longer game."},{"type":"steps","heading":"How to play","items":["You are the Captain, standing in the middle. Name the four sides of the space: bow (front), stern (back), port (left) and starboard (right).","Call a command. The players do it as fast as they can.","In a longer game, the last player to get it right, or anyone doing the wrong action, is out. Play until one player is left."]},{"type":"box","heading":"Commands you can use","items":["**Bow, stern, port, starboard:** run to that side.","**Captain''s coming:** run to the middle line, salute and call \"Aye aye, Captain!\".","**Scrub the deck:** kneel and scrub the floor.","**Climb the rigging:** mime climbing a rope ladder.","**Crow''s nest:** shade your eyes and look out.","**Cannonball:** duck down.","**Submarine:** lie on your back with one leg up as a periscope.","**Stormy waters:** sway and wave your arms.","**Man overboard:** find a partner and pull each other up.","**Lifeboats of three:** sit in lines of three and row.","**Freeze:** stop where you are."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known. 3 different lists of commands in Belmont Scouts'' folders were combined here."}]'::jsonb, 7),
  ('active', 'clean-your-room', 'Clean Your Room', 'hall', 'Team game · Cubs', 'Two teams · hall', '[{"type":"verse","text":"Two teams race to clear their side of a messy \"room\" by throwing everything over the wall."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Sheet or tarp, hung across the hall at about Cub head height"},{"qty":null,"item":"A big pile of soft clothes or other soft items"}]},{"type":"steps","heading":"How to play","items":["Hang the sheet to divide the hall in two. One team goes on each side.","Share the clothes out at random between both sides.","On \"Go\", each Cub picks up one item at a time and throws it over the sheet into the other room.","Call time after a few minutes. The team with the cleaner room wins. Or play until one room is empty."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 8),
  ('active', 'balloon-stampede', 'Balloon Stampede', 'hall', 'Chasing · Cubs', 'Any number · hall', '[{"type":"verse","text":"Every Cub has a balloon on one ankle. Burst the others'', and protect your own."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Balloon per Cub"},{"qty":1,"item":"Piece of string or ribbon per Cub"}]},{"type":"safety","heading":"Safety","items":["Check nobody is allergic to latex. Clear the room of furniture. Pick up burst balloon pieces straight away."]},{"type":"steps","heading":"How to play","items":["Tie a balloon to each Cub''s ankle with a short piece of string.","On \"Go\", everyone tries to stamp on other Cubs'' balloons while keeping their own safe.","A Cub whose balloon bursts is out and sits at the side.","The last Cub with a balloon wins."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com). This is also known as \"Balloon Derby\"."}]'::jsonb, 9),
  ('active', 'circle-line', 'Circle Line', 'hall', 'Ball game · Cubs', 'One Six in the middle · hall', '[{"type":"verse","text":"A chain of Cubs in the middle tries not to be hit by a ball passed around the circle."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Soft ball"}]},{"type":"safety","heading":"Safety","items":["Use a very soft ball and aim low. No throwing at heads."]},{"type":"steps","heading":"How to play","items":["The pack makes a circle. One Six stands in the middle in a line, each Cub holding the waist or shoulders of the one in front. The chain must not break.","The circle passes the ball around and across, then aims at the back Cub of the chain, below the knee.","The Cub who gets a hit goes to the front of the chain. The Cub who was hit takes their place in the circle.","Passing the ball to the best thrower, not just throwing wildly, makes it work better."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 10),
  ('active', 'circle-catch-up', 'Circle Catch-up', 'hall', 'Passing · Cubs', 'Whole pack in a circle · hall', '[{"type":"verse","text":"Two bean bags race around a circle: one runs, and one chases."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Bean bags (one \"possum\", one \"dog\")"}]},{"type":"steps","heading":"How to play","items":["The pack sits or stands in a circle.","Start the possum round the circle, passing it hand to hand.","A moment later, start the dog the same way, in the same direction.","The dog must catch up with the possum before the possum gets back to where it started.","Swap in new Cubs to start each round."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 11),
  ('active', 'hand-soccer', 'Hand Soccer', 'hall', 'Floor game · Cubs', 'Two teams · hall', '[{"type":"verse","text":"Two teams sit in two lines, feet to bottoms, and try to row a ball to their end using only one hand."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Ball"}]},{"type":"steps","heading":"How to play","items":["Two teams sit in parallel lines facing opposite ways, about 1.2 m apart, each Cub''s feet touching the bottom of the Cub in front.","Mark the halfway point and put the ball there.","On \"Row!\", each Cub uses only their inner hand to push the ball along the floor towards their team''s front.","A goal is scored when the ball reaches the front of a team. The ball must stay on the floor.","For a change, turn around and use the other hands."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 12),
  ('active', 'fire-circle', 'Fire Circle', 'anywhere', 'Circle running · Cubs', 'Pack in pairs · hall or field', '[{"type":"verse","text":"Cubs run around a circle until the \"fire is out\", then hurry to find their partner."},{"type":"steps","heading":"How to play","items":["Pair the Cubs. One of each pair stands in an inner circle and the other in an outer circle, facing each other, with two to four paces between pairs.","One extra Cub stands in the middle and calls \"The mountain is on fire. Run!\".","The outer circle turns left and runs round the outside of the circle.","When the middle Cub calls \"The fire is out!\", everyone looks for their original partner. Nobody may cross the circle. The middle Cub tries to take a partner too.","Whoever is left without a partner goes in the middle. Inner and outer circles swap places each round."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 13),
  ('active', 'animal-tag', 'Animal Tag', 'anywhere', 'Chasing · Cubs', 'Two teams · hall or field', '[{"type":"verse","text":"Two teams, Rats and Rabbits. Listen for your name and run, or chase."},{"type":"steps","heading":"How to play","items":["Mark a safe wall or line at each end. Make two lines, a couple of metres apart, facing the leader: Rats and Rabbits.","Call one animal. If you call \"Rats\", the Rats run to their wall and the Rabbits chase them.","Anyone tagged before reaching the wall joins the other team.","Trick them by calling words that start with R, like \"rice\" or \"rhubarb\", and see who moves."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 14),
  ('active', 'knock-down', 'Knock Down', 'hall', 'Ball game · Cubs', 'Whole pack in a circle · hall', '[{"type":"verse","text":"Knock down all three tins in the middle, while the Cub in the centre stands them up again."},{"type":"kit","heading":"You need","items":[{"qty":3,"item":"Tins, stacked or stood up"},{"qty":2,"item":"or 3 × Soft balls"}]},{"type":"steps","heading":"How to play","items":["The pack stands in a big circle. One Cub stands in the middle by the tins and tries to set up any that fall.","The circle rolls or throws soft balls to knock the tins over.","When all three are down at once, the Cub who knocked over the last tin swaps places with the one in the middle."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 15),
  ('active', 'pack-pass', 'Pack Pass', 'anywhere', 'Ball skills · Cubs', 'Patrols in pairs · hall or field', '[{"type":"verse","text":"A throwing and catching challenge that gets harder every round."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Ropes, to mark lines"},{"qty":1,"item":"Ball per group"}]},{"type":"steps","heading":"How to play","items":["Lay two ropes 3 to 5 m apart. Each patrol splits in half, one half behind each rope, facing the other.","The first Cub throws to the first Cub opposite, who passes on in turn, working along the line.","If anyone drops the ball, begin again.","When a team makes it to the end, move the ropes further apart for the next round."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 16),
  ('active', 'postal-delivery', 'Postal Delivery', 'hall', 'Running and listening · Cubs', 'Whole pack · hall', '[{"type":"verse","text":"Letters walk, parcels hop and telegrams run. Make your delivery before time is up."},{"type":"steps","heading":"How to play","items":["Half the Cubs sit in a circle and each choose a town. The rest are the post: Letters (who walk), Parcels (who hop) or Telegrams (who run).","Call out a type of mail and several towns, for example \"Telegram, Brisbane and Cairns\".","Those Cubs move as their mail type does, and swap places with the towns that were called.","The slowest delivery is \"returned to sender\" and misses the next round."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 17),
  ('active', 'im-mowgli-king-of-the-jungle', 'I''m Mowgli, King of the Jungle', 'anywhere', 'Duel · Cubs', 'Pairs in a circle · hall or field', '[{"type":"verse","text":"A friendly one-legged shoulder-bump duel from the jungle."},{"type":"steps","heading":"How to play","items":["The pack sits in a circle. One Cub stands in the middle on one leg with their arms folded, and calls: \"I''m Mowgli, King of the Jungle, and I challenge (name)!\".","The challenged Cub comes in, also on one leg with arms folded.","They bump shoulders, trying to make the other put their foot down, unfold their arms, leave the circle or fall over.","The winner is the new Mowgli and challenges somebody else."]},{"type":"safety","heading":"Safety","items":["Bump with shoulders only. No pushing, no grabbing."]},{"type":"note","text":"A traditional Cub game, listed by Pack 568 and by UK Scouts in their traditional Cub games."}]'::jsonb, 18),
  ('active', 'monkey-game', 'Monkey Game', 'anywhere', 'Listening · Cubs', 'Whole pack · hall or field', '[{"type":"verse","text":"Cubs act as the wild, noisy Bandar-log monkeys until a leader signals, then change in a flash."},{"type":"steps","heading":"How to play","items":["Everyone behaves like out-of-control monkeys, running about and chattering.","At any moment a leader makes a Cub sign or call, such as \"Stop, look, listen\", the salute and handshake, form two lines, or the Grand Howl.","Everyone must do that action at once, in silence if it is a \"stop\" signal.","Give a point to the Six that is last to be ready, and see which Six has the fewest at the end."]},{"type":"note","text":"A traditional Cub game, listed by Pack 568 and by UK Scouts in their traditional Cub games."}]'::jsonb, 19),
  ('active', 'poison-ball', 'Poison Ball', 'anywhere', 'Dodging · Cubs and Scouts', 'Whole pack · hall or field', '[{"type":"verse","text":"Leaders throw soft balls at the pack. Anyone hit below the knees joins the throwers."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"or 3 × Large soft balls"}]},{"type":"safety","heading":"Safety","items":["Throw gently and low. No head shots."]},{"type":"steps","heading":"How to play","items":["A few leaders stand around the edge of a large area. Everyone else is in the middle.","The leaders roll or throw balls at the players, who duck and dodge.","Anyone touched below the knees goes to the edge to help throw.","The last Cub in the middle wins."]},{"type":"box","heading":"Variations","items":["Play in two teams in a 4 m square: one team outside throws, the other dodges inside."]},{"type":"note","text":"A traditional Cub game, listed by Pack 568 and by UK Scouts in their traditional Cub games."}]'::jsonb, 20),
  ('active', 'balloon-tennis', 'Balloon Tennis', 'hall', 'Seated game · Cubs', 'Two teams · hall', '[{"type":"verse","text":"A seated game for a wet night. Bat the balloons over to the other side without leaving your chair."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"or 3 × Balloons"},{"qty":null,"item":"Chairs for everyone"}]},{"type":"steps","heading":"How to play","items":["Two teams sit on chairs facing each other, with a gap of a few metres in between.","Put two or three balloons in play.","Everyone stays on their chair and bats the balloons, trying to get them to land behind the other team.","Each balloon that lands behind a team scores a goal. Put it back into play."]},{"type":"note","text":"A traditional Cub game, listed by Pack 568 and by UK Scouts in their traditional Cub games."}]'::jsonb, 21),
  ('active', 'chook-chase', 'Chook Chase', 'anywhere', 'Ribbon snatching · Cubs', 'Sixes · hall or field', '[{"type":"verse","text":"Each Six tries to collect a ribbon of every colour in a ribbon-snatching chase."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Ribbons per Cub, each Six in its own colour"},{"qty":null,"item":"Several buckets, around the edge"}]},{"type":"steps","heading":"How to play","items":["Each Cub tucks two ribbons of their Six''s colour into the back of their belt, half showing.","The goal is for each Six Leader to end up with one ribbon of every colour.","Cubs may take one ribbon from another Cub and bring it to their Six Leader.","If the Leader already has that colour, the Cub puts the ribbon in a bucket at the side. A Cub may also collect one ribbon from a bucket instead of from a player.","The first Six to complete a set wins."]},{"type":"note","text":"A Belmont Scouts game. Probably written by a Belmont leader."}]'::jsonb, 22),
  ('active', 'fruit-salad', 'Fruit Salad', 'hall', 'Chairs · Cubs', 'Whole pack · hall', '[{"type":"verse","text":"A chair-swapping game with one chair too few. Call the fruit, and swap places."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Chair per player, less one"}]},{"type":"steps","heading":"How to play","items":["Put the chairs in a circle, one fewer than the number of players. One player stands in the middle as \"it\".","Go round the circle naming each Cub apple, orange or pear.","The player in the middle calls a fruit. Everyone of that fruit stands up and swaps to a different chair. The player in the middle tries to grab a seat.","Whoever is left standing is the next \"it\".","\"It\" can also call \"Fruit salad!\", and everyone must swap."]},{"type":"box","heading":"Variations","items":["Use a theme, such as footballers or animals, instead of fruit."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 23),
  ('active', 'fruit-salad-tunnel-race', 'Fruit Salad (tunnel race)', 'anywhere', 'Running race · Cubs', 'Pairs · hall or field', '[{"type":"verse","text":"A team race through a tunnel of hands, when your fruit is called."},{"type":"steps","heading":"How to play","items":["Pair the Cubs. Each pair picks a fruit, then the pairs stand in two lines facing each other, hands joined to form a tunnel.","Call a fruit. That pair runs through the tunnel, back around the outside, and into their own place.","For a team version, make each line a team and score each race.","Mix it up with animals, and make the animal noise as you run."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 24),
  ('active', 'rob-the-nest', 'Rob the Nest', 'hall', 'Snatching · Cubs', 'Sixes · hall', '[{"type":"verse","text":"Each Six guards a nest of balls, and the supply in the middle gets smaller every round."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Hoop or bucket per Six, as a nest, and 1 for the middle"},{"qty":null,"item":"Balls, enough that each nest can hold several"}]},{"type":"steps","heading":"How to play","items":["Put all the balls in the middle hoop at the start. Each Six sets its nest at its home base.","When you say \"Go\", one Cub from each Six runs to the middle (or to another Six''s nest), takes one ball, and brings it home. Then the next Cub goes.","Each Six tries to fill its nest to the target number.","Take away one ball each round, so there are never enough for everyone."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 25),
  ('active', 'tug-of-war', 'Tug of War', 'outdoors', 'Team game · Cubs and Scouts', 'Two teams · field', '[{"type":"verse","text":"The classic rope pull, with a fair way to keep it safe."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Long, thick rope"},{"qty":3,"item":"Cones, for the centre and each side line"}]},{"type":"safety","heading":"Safety","items":["Equal numbers on each side. Adults stand at the back of the rope behind the youngest players.","Drop the rope on command. Nobody wraps the rope around a hand."]},{"type":"steps","heading":"How to play","items":["Lay the rope across the ground with the centre over the middle cone and a cone to each side.","Two teams of equal numbers take hold of the rope.","On \"Pull!\", each team tries to haul the other team''s marker past the line.","Play a mixed round with everyone together, then a round of Cubs against adults."]},{"type":"note","text":"A Belmont Scouts game. Played on Belmont''s Fathers Day night."}]'::jsonb, 26),
  ('active', 'balloon-volleyball', 'Balloon Volleyball', 'hall', 'Ball game · Cubs', 'Two teams · hall', '[{"type":"verse","text":"Volleyball with a balloon, which is slower and a lot safer in a hall."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"A bag of balloons"},{"qty":null,"item":"Optional: a net or rope across the middle"}]},{"type":"steps","heading":"How to play","items":["Mark a court. Use a net or a rope if you have one, or just a line.","Two teams keep the balloon in the air and hit it over to the other side.","If the balloon touches the ground on your side, the other team scores.","With a big pack, split the hall into four courts."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 27),
  ('active', 'blob', 'Blob', 'anywhere', 'Chain tag · Cubs and Scouts', 'Any number · hall or field', '[{"type":"verse","text":"A tag game where the chaser grows into a long chain as it catches people."},{"type":"steps","heading":"How to play","items":["Agree boundaries. Two players join hands to start the Blob.","The Blob chases the others. Only the free hands at each end can tag.","Everyone tagged joins hands to the Blob, making it longer.","The last player free is the winner and starts the next game."]},{"type":"note","text":"The game also appears as \"Germs\". For other chain tag games, see \"Pairs Tag\" and \"Caterpillar Tag\"."},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 28),
  ('active', 'pairs-tag', 'Pairs Tag', 'anywhere', 'Chain tag · Scouts', 'Odd number · hall or field', '[{"type":"verse","text":"A tag game where a chain of two grows to three, and then splits into two pairs."},{"type":"steps","heading":"How to play","items":["Two players link arms or hands and chase the others.","When they catch someone, the chain is three. When they catch another, it becomes four, and splits into two pairs, each chasing.","Continue until one player is not caught, who wins."]},{"type":"box","heading":"Variations","items":["**Amoeba tag:** the chain can stay together or split into twos, as the players like.","**Train chase:** the tagger catches onto the shoulders of the person ahead. At four they split into two trains.","**Dodge the Ute:** one tagger starts. Anyone tagged links arms with them. At four they split."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author. Pairs Tag also appears as Belmont leader Greg''s version. Amoeba Tag, Train Chase and Dodge the Ute are variations found in Belmont''s Scout folders."}]'::jsonb, 29),
  ('active', 'caterpillar-tag', 'Caterpillar Tag', 'anywhere', 'Freeze tag · Scouts', 'Pairs · hall or field', '[{"type":"verse","text":"A freeze tag played in pairs, where you are freed when another pair joins hands with you."},{"type":"steps","heading":"How to play","items":["Everyone pairs up and holds hands. Choose which pairs are the taggers.","On \"Go\", the taggers chase the other pairs.","A tagged pair freezes. Another free pair can release them by joining hands with them, and they now stay together as a group of four.","Groups can keep growing. Play for a set time, or until everyone is frozen."]},{"type":"note","text":"From a PE warm-up games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 30),
  ('active', 'dragons', 'Dragons', 'anywhere', 'Chasing game · Scouts', 'Patrols · hall or field', '[{"type":"verse","text":"Each patrol is a dragon. The head tries to catch the tail of another dragon."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Rag or handkerchief per patrol, as a tail"}]},{"type":"steps","heading":"How to play","items":["Each patrol lines up in a chain, arms around the waist of the Scout in front.","Tuck a rag in the back pocket or belt of the last Scout.","The aim is for the head of one dragon to grab the tail of another, while keeping their own tail safe.","If a dragon breaks apart, it must stop and reconnect before it can carry on.","A caught tail means that dragon is out. The last dragon wins."]},{"type":"note","text":"A Belmont Scouts game. From Games Night, July 2023, with credit to Belmont leaders."}]'::jsonb, 31),
  ('active', 'giants-wizards-and-elves', 'Giants, Wizards and Elves', 'outdoors', 'Chasing game · Scouts', 'Two teams · hall or field', '[{"type":"verse","text":"A team version of rock, paper, scissors, with a chase if you lose."},{"type":"steps","heading":"How to play","items":["Giants squash elves. Elves outwit wizards (they chew at their legs). Wizards zap giants.","Each team huddles and secretly decides to be giants, wizards or elves.","The two teams line up facing each other about 1.5 m apart. After \"Three, two, one, go!\" each team acts out its choice together.","The winning team chases the losers back to their safe line. Anyone caught joins the winners.","A matching choice is a draw: go again.","Play on until one team has everybody, or time is up."]},{"type":"note","text":"A Belmont Scouts game. Shared by Josh Drake."}]'::jsonb, 32),
  ('active', 'ship-sand-shore', 'Ship, Sand, Shore', 'anywhere', 'Reaction game · Scouts', 'Any number · hall or field', '[{"type":"verse","text":"Jump to the right side of a rope when you hear the call. Jump when you shouldn''t, and you''re out."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Long rope laid straight on the ground"}]},{"type":"steps","heading":"How to play","items":["Everyone stands on the rope, with one foot on each side. This is \"Sand\".","The side with both feet on one side is \"Ship\", and the other side is \"Shore\".","Call \"Ship\", \"Shore\" or \"Sand\". Players jump so that they are in the right place.","A player who is too slow or lands in the wrong place is out.","Call the place players are already standing, to trick them into jumping.","The last one standing wins."]},{"type":"note","text":"A Belmont Scouts game. Shared by Josh Drake."}]'::jsonb, 33),
  ('active', 'steal-the-bacon', 'Steal the Bacon', 'anywhere', 'Snatching game · Cubs and Scouts', 'Two teams · hall or field', '[{"type":"verse","text":"Two teams are numbered off. When your number is called, run to grab the bacon without getting tagged."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Small object, as the \"bacon\" (a cloth, bean bag or beanie)"},{"qty":2,"item":"Ropes or lines, one for each team, about 10 m apart"}]},{"type":"steps","heading":"How to play","items":["Split the group in two teams and number every player. The teams line up facing each other, with the bacon in the middle.","Call a number. The player with that number on each team runs to the middle to grab the bacon and take it back to their own side.","The other player tries to tag them. You can only be tagged when you hold the bacon.","A tagged player drops the bacon for the other to grab. The team scores a point when the bacon crosses its line, or when its player tags an opponent with the bacon.","Put the bacon back and call a new number."]},{"type":"box","heading":"Variations","items":["Call several numbers at once, with more than one bacon.","Blindfold one player in each patrol and let the patrol guide them to the bacon with their voices."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author. Three different versions in Belmont''s folders were combined."}]'::jsonb, 34),
  ('active', 'capture-the-fort', 'Capture the Fort', 'outdoors', 'Team game · Scouts', '14 or more · field', '[{"type":"verse","text":"Attackers kick a ball \"bomb\" at a fort of linked players, who defend with their bodies and one hand."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Soccer ball or foam ball"}]},{"type":"steps","heading":"How to play","items":["One team makes the fort: a circle facing outward, each player with their left hand on the right shoulder of the player next to them. Their leader stands in the middle.","The other team spreads out around the fort.","Drop the ball to the attackers. They try to kick it between the defenders or over the top.","If the ball touches the ground inside the fort, it explodes. The leader inside can catch it and throw it back before it lands.","Swap roles after each explosion, or after a set time."]},{"type":"note","text":"Based on a game at Boy Scout Trail (boyscouttrail.com), kept in Belmont Scouts'' folders."}]'::jsonb, 35),
  ('active', 'chinese-wall', 'Chinese Wall', 'hall', 'Running game · Scouts', 'Any number · hall', '[{"type":"verse","text":"Run past the defenders on the wall without being tagged. Anyone caught joins the wall."},{"type":"steps","heading":"How to play","items":["Chalk two parallel lines about 3 m apart across the middle of the hall. This is the wall.","Two defenders stand on the wall. Everyone else lines up at one end.","On \"Go\", the runners dash to the other end of the hall, avoiding the defenders who may not leave the wall.","Anyone tagged joins the wall as a defender.","The last runner is the winner."]},{"type":"note","text":"The name here comes from the old file. You might prefer to call it \"The Wall\"."},{"type":"note","text":"A Belmont Scouts game. Shared by Greg."}]'::jsonb, 36),
  ('active', 'balloon-basketball', 'Balloon Basketball', 'hall', 'Ball game · Cubs and Scouts', 'Two teams · hall', '[{"type":"verse","text":"Bat a balloon to your goalkeeper, who catches it in a bucket while standing on a chair."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Balloon"},{"qty":2,"item":"Chairs"},{"qty":2,"item":"Buckets"}]},{"type":"steps","heading":"How to play","items":["Put a chair at each end. A goalkeeper stands on each chair, holding a bucket.","Split everyone into two teams. Each team tries to hit the balloon to its goalkeeper to be caught in the bucket.","Nobody may grab the balloon, only tap it.","Take turns as goalkeepers."]},{"type":"safety","heading":"Safety","items":["Chairs are steady and on a non-slip floor. An adult stands nearby."]},{"type":"note","text":"Based on a game from Tyakunda Scout Group, Scouts Queensland."}]'::jsonb, 37),
  ('active', 'turtle-soccer', 'Turtle Soccer', 'anywhere', 'Circle game · Scouts', 'A circle of 8 or more · hall or field', '[{"type":"verse","text":"Stand in a circle with your legs wide, and bat the ball through the legs of the others."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Soccer ball or volleyball"}]},{"type":"steps","heading":"How to play","items":["Stand in a circle facing inward, feet wide apart so your outside foot touches your neighbour''s. Legs must stay straight.","The gap between your legs is your goal.","Bat the ball with your hands to try to get it between somebody else''s legs. You may not hold or throw it.","If the ball goes through your legs, you must put one hand behind your back. If it happens again, you are out and the circle closes up.","Play until two are left."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 38),
  ('active', 'spud', 'Spud', 'outdoors', 'Dodging game · Scouts', 'Any number · field', '[{"type":"verse","text":"Run when your number is called, then freeze when someone calls \"Spud\". The thrower takes three steps and throws."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Soft ball"}]},{"type":"steps","heading":"How to play","items":["Number all the players. They stand close in a circle, with one player in the middle who holds the ball.","The middle player throws the ball high and calls a number. Everyone scatters except the player with that number.","That player grabs the ball and shouts \"Spud!\". Everyone freezes.","The player with the ball takes up to three giant steps toward anyone they choose and throws.","The target may move everything except their feet. If hit, the target gets a letter of S-P-U-D. If missed, the thrower gets a letter.","The person who got the letter throws next. After four letters, a player is out."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 39),
  ('active', 'chair-dodge', 'Chair Dodge', 'hall', 'Circle game · Scouts', 'A circle of 8 or more · hall', '[{"type":"verse","text":"Hold hands in a circle and steer other players into the chair in the middle."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Chair"}]},{"type":"safety","heading":"Safety","items":["No twisting or wrenching arms. Stop any round that gets rough."]},{"type":"steps","heading":"How to play","items":["Everyone holds hands in a circle with the chair in the middle.","Pull and steer the circle so that others bump into the chair.","A player who touches the chair is out. If the circle breaks, both players beside the break are out.","The last player in wins."]},{"type":"box","heading":"Variations","items":["Put more chairs outside the circle."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 40),
  ('active', '4-way-tug-o-war', '4-Way Tug-o-War', 'outdoors', 'Team game · Scouts', 'Four teams · field', '[{"type":"verse","text":"A tug of war with four teams at once, pulling toward the four corners of a square."},{"type":"kit","heading":"You need","items":[{"qty":4,"item":"Ropes, about 7 m each, knotted into a square"},{"qty":1,"item":"Rag or kerchief"}]},{"type":"steps","heading":"How to play","items":["Tie the four ropes together into a loop, and lay it out as a square with the knots at the corners.","Put the rag in the centre. One team lines up along each side.","On \"Go\", everyone picks up the rope and pulls away from the centre.","After a set time, call \"Stop\". The team that has moved furthest from the centre wins."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 41),
  ('active', 'rooster-fights', 'Rooster Fights', 'anywhere', 'Duel · Scouts', 'Pairs · hall or field', '[{"type":"verse","text":"Hop on one foot, holding the other, and shoulder-bump your opponent off balance."},{"type":"safety","heading":"Safety","items":["Shoulders only: no grabbing, pushing or tripping. Mark a clear, soft area."]},{"type":"steps","heading":"How to play","items":["Mark a circle on the ground.","Each Scout hops on one foot, holding the other by the ankle behind them.","Two Scouts face off in the circle and bump shoulders.","You lose if you lose your balance, let go of your ankle, fall, or step out of the circle."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 42),
  ('active', 'crab-ball', 'Crab Ball', 'hall', 'Ball game · Scouts', 'Two teams · hall or field', '[{"type":"verse","text":"Football played in the crab position."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Ball"}]},{"type":"steps","heading":"How to play","items":["Mark two goal lines about 12 m apart and line up a team on each.","Everyone is in the crab position at all times, on hands and feet with the tummy up.","Try to kick the ball into the other team''s goal."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 43),
  ('active', 'the-sieve', 'The Sieve', 'hall', 'Chasing game · Scouts', 'Two teams · hall', '[{"type":"verse","text":"Attackers try to run through defenders without losing their armband."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Neckerchief per attacker"}]},{"type":"steps","heading":"How to play","items":["Mark rows of lines across the space, with every second line a safe zone.","Defenders spread out along the lines. Attackers tie a neckerchief around an arm.","Attackers try to cross to the far goal without having their armbands pulled off.","Anyone who loses an armband is captured. Swap roles."]},{"type":"note","text":"The original instructions here were hard to follow. Try a short round first and adjust the rules."},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 44),
  ('active', 'blanket-volleyball', 'Blanket Volleyball', 'outdoors', 'Team game · Scouts', 'Two teams · field or hall', '[{"type":"verse","text":"Volleyball where each team uses a blanket to catch and launch the ball."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Blankets"},{"qty":1,"item":"Light ball"},{"qty":null,"item":"Optional: a net or rope across the middle"}]},{"type":"steps","heading":"How to play","items":["Make two teams. Each team holds a blanket tight at its edges.","To serve, put the ball on the blanket, slacken it, then pull it tight so the ball flies over the net.","The other team catches the ball on their blanket and sends it back.","Score a point when the ball lands in the other team''s area, or when a team fails to return it."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 45),
  ('active', 'octopus-tag', 'Octopus Tag', 'hall', 'Running game · Scouts', '10 or more · hall', '[{"type":"verse","text":"The more people the octopus catches, the more arms it has."},{"type":"steps","heading":"How to play","items":["One player stands in the middle as the octopus. Everyone else stands at one end of the hall.","On \"Go\", everyone runs to the other end. The octopus tags as many as it can.","Anyone tagged stays where they were caught, sits down, and may only tag by reaching with their arms.","Keep crossing back and forth. The last runner starts the next round as the octopus."]},{"type":"note","text":"From a PE warm-up games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 46),
  ('active', 'alligator-in-the-swamp', 'Alligator in the Swamp', 'anywhere', 'Running game · Scouts', '10 or more · hall or field', '[{"type":"verse","text":"Runners dash across the swamp, trying not to be caught by the alligators."},{"type":"steps","heading":"How to play","items":["Mark two safe lines. One group lies on their tummies at the middle, as alligators. The other group is the runners, at one end.","On \"Go\", the runners dash across to the other line. The alligators get up and chase.","Tagged runners sit out until the next game.","Swap ends each time. When three to five runners are left, begin again."]},{"type":"note","text":"From a PE warm-up games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 47),
  ('active', 'skunk-tag-hoops', 'Skunk Tag (hoops)', 'hall', 'Tag · Scouts', '8 or more · hall', '[{"type":"verse","text":"A tag game with hula-hoop safe zones and a skunk''s home in the middle."},{"type":"kit","heading":"You need","items":[{"qty":5,"item":"Hula hoops"}]},{"type":"steps","heading":"How to play","items":["Put a hoop at each of four corners, as safe zones, and one in the middle as the skunk''s home.","Choose two players as skunks and put them in the middle.","On \"Go\", the skunks chase. A player in a safe hoop is safe for up to 20 seconds, or until another player steps in behind them. Only one player may be in a hoop.","A player who gets tagged becomes a skunk. They must run to the middle hoop and shout \"New skunk!\" before chasing."]},{"type":"note","text":"This is not the same game as \"Skunk Tag (balance)\"."},{"type":"note","text":"From a PE warm-up games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 48),
  ('active', 'one-behind', 'One Behind', 'hall', 'Movement game · Scouts', 'Any number · hall', '[{"type":"verse","text":"A warm-up where everyone copies the leader, but one move behind."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Music, if you like"}]},{"type":"steps","heading":"How to play","items":["Everyone finds a spot with room to move.","The leader does an exercise or stretch. The group stands at attention.","When the leader switches to a new move, the group starts the move the leader just finished.","Keep going for about three minutes, working from standing moves down to the floor."]},{"type":"note","text":"From a PE warm-up games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 49),
  ('active', 'locomotor-races', 'Locomotor Races', 'outdoors', 'Running game · Scouts', 'Any number · hall or field', '[{"type":"verse","text":"Short races where each team has to move in a different style, like hopping or skipping."},{"type":"steps","heading":"How to play","items":["Mark a start line and a finish line, and a waiting line about 1.5 m behind the start line.","Number everyone from 1 to 6.","Call a movement, such as hopping or skipping. Then call a number. Those players race across, then jog back round the side to the waiting line.","Call the next number as soon as the last group has set off, so there is little resting.","After each group has had a couple of goes, pick a new movement."]},{"type":"note","text":"From a PE warm-up games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 50),
  ('active', 'exercise-square', 'Exercise Square', 'hall', 'Movement game · Scouts', 'Any number · hall', '[{"type":"verse","text":"Everyone stands in a square. The leader in the middle picks an exercise and everyone copies."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Music, if you like"}]},{"type":"steps","heading":"How to play","items":["Everyone stands in a large square, an arm''s length from the next person.","A leader goes in the middle and does an exercise. Everyone copies.","After 20 to 30 seconds, blow a whistle. The leader picks a new leader, and everyone jogs on the spot meanwhile.","Continue for three to five minutes."]},{"type":"box","heading":"Variations","items":["Do it with skipping ropes, but only choose moves that everyone has already practised."]},{"type":"note","text":"From a PE warm-up games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 51),
  ('active', 'galloping-lizzie', 'Galloping Lizzie', 'outdoors', 'Ball game · Scouts', 'Any number · hall or field', '[{"type":"verse","text":"One player throws a soft ball at the others. If you''re hit, you''re next."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Sponge or soft ball"}]},{"type":"steps","heading":"How to play","items":["Everyone spreads out. One player is \"it\" and holds the ball.","\"It\" throws the ball at another player. Whoever is hit becomes \"it\".","To make it trickier, say how they must throw: underarm, left-handed, backwards, and so on."]},{"type":"note","text":"From a PE warm-up games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 52),
  ('active', 'spiders-and-scorpions', 'Spiders and Scorpions', 'hall', 'Crawling tag · Scouts', '10 or more · hall', '[{"type":"verse","text":"Scorpions crawl face-down trying to sting, and spiders crawl face-up."},{"type":"steps","heading":"How to play","items":["Choose four players to be scorpions. They crawl on hands and feet, tummy down.","Everyone else is a spider, crawling on all fours with their tummy up.","If a scorpion tags a spider, the spider must hold one hand or foot up in the air, a three-point balance, until the game ends.","Play until all spiders are stung or time runs out."]},{"type":"box","heading":"Variations","items":["Add some special spiders who can cure the stung spiders by tagging them."]},{"type":"note","text":"From a PE warm-up games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 53),
  ('quiet', 'ships-and-lighthouses', 'Ships and Lighthouses', 'hall', 'Listening · Cubs', '6 or more · hall', '[{"type":"verse","text":"A blindfolded \"ship\" steers toward a lighthouse''s beep and away from the rocks'' wave sounds."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Blindfold per ship"}]},{"type":"safety","heading":"Safety","items":["Rocks stand still with their hands low. A leader walks alongside the ship."]},{"type":"steps","heading":"How to play","items":["One Cub is the ship and is blindfolded at one end of the hall. Another Cub is the lighthouse at the far end, who beeps or makes a distinctive noise.","The rest of the pack spread out in between as rocks.","The ship walks toward the lighthouse. If it nears a rock, the rock makes a \"shshsh\" wave sound to warn it away.","When the ship reaches the lighthouse, choose new players.","After a couple of rounds, use two ships and two lighthouses with different sounds."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 1),
  ('quiet', 'scotland-yard', 'Scotland Yard', 'hall', 'Observation · Cubs', '9 or more · hall', '[{"type":"verse","text":"Detectives study a row of hands, then try to pick whose hands appeared through the door."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Cloth or sheet to cover arms"}]},{"type":"steps","heading":"How to play","items":["Divide the pack into three groups: thieves and two detective teams.","The detectives study the thieves'' hands closely, then the thieves leave the room.","One thief at a time reaches in under the cloth so only their hands show. Each detective team writes down who it thinks it is.","Reveal the identities only once every thief has been through the door. Each correct guess earns a point for that team.","Swap roles and play again."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 2),
  ('quiet', 'sharp-ears', 'Sharp Ears', 'anywhere', 'Listening · Cubs', 'Pack in a circle · hall or field', '[{"type":"verse","text":"Can you tell who is speaking, with your eyes covered?"},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Blindfold"}]},{"type":"steps","heading":"How to play","items":["The pack sits or stands in a circle. One Cub stands blindfolded in the middle.","A leader points to one Cub, who says the middle Cub''s name softly.","The blindfolded Cub has three guesses to name who spoke.","If it''s too easy, ask the speaker to make an animal noise instead."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 3),
  ('quiet', 'creep-mouse', 'Creep Mouse', 'anywhere', 'Silent game · Cubs', 'Pack in a circle · hall or field', '[{"type":"verse","text":"Mice creep towards a blindfolded cat, and the cat points at anything it hears."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Blindfold"}]},{"type":"steps","heading":"How to play","items":["A Cub sits blindfolded in the middle as the cat. The mice start at the edge.","Everyone must be completely silent. One mouse at a time creeps towards the cat.","If the cat hears a mouse, it points in that direction. If it points correctly, the mouse is caught and sits down where it was.","When all the mice have had a go, the mouse closest to the cat wins."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 4),
  ('quiet', 'sticky-toffee', 'Sticky Toffee', 'hall', 'Pulling apart · Cubs', 'Whole pack · hall', '[{"type":"verse","text":"The pack lies in a clump like toffee, and the leader pulls it apart."},{"type":"safety","heading":"Safety","items":["Gentle pulling only, by the legs or ankles, and never by clothes or hair."]},{"type":"steps","heading":"How to play","items":["All the Cubs lie down in a circle, holding on to each other''s wrists and legs. This is the toffee.","A leader grasps one Cub''s legs and gently pulls them out of the circle.","That Cub then pulls other Cubs from the circle, and so on, until the whole toffee has been pulled apart.","Cubs who can''t be part of the toffee can pull or call out where to go next."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 5),
  ('quiet', 'balloon-stomp', 'Balloon Stomp', 'hall', 'Blindfold game · Cubs', 'One at a time · hall', '[{"type":"verse","text":"Walk to the right balloon blindfolded, then stomp it in three tries."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Several coloured balloons"},{"qty":1,"item":"Blindfold"}]},{"type":"safety","heading":"Safety","items":["A leader walks beside the blindfolded Cub. Other Cubs stay outside the space."]},{"type":"steps","heading":"How to play","items":["Place several coloured balloons on the ground at the far end. Let the Cubs look at them first.","Blindfold one Cub at a time.","A leader calls a colour. The Cub walks toward that balloon and has three stomps to burst it."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 6),
  ('quiet', 'kims-game', 'Kim''s Game', 'anywhere', 'Memory · Cubs and Scouts', 'Any number · hall or field', '[{"type":"verse","text":"Look at a tray of objects, then try to remember them once they''re covered."},{"type":"kit","heading":"You need","items":[{"qty":10,"item":"to 20 small objects on a tray"},{"qty":1,"item":"Cloth to cover them"},{"qty":null,"item":"Paper and pencils"}]},{"type":"steps","heading":"How to play","items":["Lay the objects out on a tray or table and give everyone a minute to look.","Cover the tray.","Each Cub or patrol writes down as many objects as they can remember.","Lift the cloth and check. The most correct wins."]},{"type":"box","heading":"Variations","items":["**Matchstick Kim''s:** arrange a few matchstick patterns, show them for a minute, then have each patrol copy the patterns.","**Kim''s book:** give each patrol a book, scales and a ruler. After a few minutes, take them away and ask questions about the weight, size, title, author, pages and chapters.","**Hide and swap:** secretly remove or move one item and ask what changed."]},{"type":"note","text":"A traditional Cub game, listed by Pack 568 and by UK Scouts in their traditional Cub games. Kim''s Game is named after Kipling''s story Kim, and was used by Baden-Powell for training scouting skills."}]'::jsonb, 7),
  ('quiet', 'blind-touch', 'Blind Touch', 'hall', 'Blindfold game · Cubs', 'Pack in a circle · hall', '[{"type":"verse","text":"Two blindfolded Cubs try to find each other by calling out."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Blindfolds"}]},{"type":"safety","heading":"Safety","items":["Everyone stands in a large circle, with space inside. A leader stays close."]},{"type":"steps","heading":"How to play","items":["The pack makes a large circle. Two Cubs stand blindfolded in the middle: Flint and Monty.","Flint calls \"Where are you, Monty?\", and Monty answers \"I''m here, Flint!\".","Flint tries to touch Monty, moving toward the voice.","When Flint touches Monty, two new Cubs take a turn."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 8),
  ('quiet', 'police-report', 'Police Report', 'hall', 'Observation · Cubs', 'Pack in Sixes · hall', '[{"type":"verse","text":"Something happens at the meeting. Can every Six describe the culprits?"},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Leaders, in disguise, in on the surprise"}]},{"type":"steps","heading":"How to play","items":["During a meeting, without warning, two disguised \"ruffians\" burst in, make a fuss with a leader, and escape.","Each Six writes down what happened and describes the ruffians as well as they can.","Compare the reports. The most accurate wins."]},{"type":"note","text":"Keep it playful. Warn parents beforehand, and tell the Cubs afterwards that it was a game."},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 9),
  ('quiet', 'matching-animals', 'Matching Animals', 'hall', 'Swapping game · Cubs', 'Whole pack · hall', '[{"type":"verse","text":"Every Cub holds half an animal name and swaps cards until they can make a complete animal."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Buckets, labelled Front and Back"},{"qty":1,"item":"Set of cards, each animal''s name split in two: the front half and the back half (for example, \"Eleph\" and \"ant\")"}]},{"type":"steps","heading":"How to play","items":["Put the front halves in one bucket and the back halves in the other, in matching numbers, so there is one of each for every Cub. It helps to bundle them in packs of four.","Each Cub takes one front half and one back half.","Ask other Cubs for a match: if your front half matches their back half, you swap, and they give you their piece that doesn''t match yours.","When a Cub makes a full animal, they put both halves back in the buckets and take a new pair.","See how many matches each Cub can make."]},{"type":"note","text":"A Belmont Scouts game."}]'::jsonb, 10),
  ('quiet', 'ping-pong-air-hockey', 'Ping Pong Air Hockey', 'anywhere', 'Table game · Cubs', '2, 4 or 8 players · table', '[{"type":"verse","text":"Blow a ping pong ball off the table, anywhere except your own edge."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Card table"},{"qty":1,"item":"Ping pong ball"}]},{"type":"steps","heading":"How to play","items":["Put one player on each side or end of the table, or two players on each side, with the ball in the middle.","Blow the ball so it falls off the table on anyone''s side except your own.","No part of you or your clothes may touch the ball or table.","Score 2 points if the ball falls off your own side. Touching the ball or table scores 1 point.","The player or team with the lowest score after the set time wins."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 11),
  ('quiet', 'game-of-possibilities', 'Game of Possibilities', 'anywhere', 'Imagination · Scouts', 'Any size patrol · anywhere', '[{"type":"verse","text":"Use an everyday object in a surprising way, and let the others guess what you''re doing."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Everyday object per patrol"}]},{"type":"steps","heading":"How to play","items":["Give each patrol one object, such as a rope, a bucket or a wooden spoon.","One Scout at a time acts out a way to use it, without speaking.","The rest of the patrol guesses. The ideas should be original, and the sillier the better.","Pass the object round until everyone has had a go."]},{"type":"note","text":"From a team-building games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 12),
  ('relay', 'rope-relay-clove-hitch', 'Rope Relay (clove hitch)', 'anywhere', 'Knot relay · Cubs', 'Sixes · hall or field', '[{"type":"verse","text":"Each Cub runs to a pole, ties a clove hitch, and runs back to tag the next."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Rope per Six"},{"qty":1,"item":"Pole per Six, set up at the far end"},{"qty":null,"item":"Judges, to check the knots"}]},{"type":"steps","heading":"How to play","items":["Split the pack into Sixes and line them up at one end.","The first Cub runs to the pole, ties a clove hitch around it with the rope, and a judge checks it.","They untie it if asked, run back and tag the next Cub, then sit down at the end of the line.","The first Six to finish with everyone sitting down wins."]},{"type":"box","heading":"Variations","items":["Change the knot each round: reef knot, bowline, sheet bend."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known. The Sixer Base night in the Cub folder uses the same idea with four knots."}]'::jsonb, 1),
  ('relay', 'increasing-relay', 'Increasing Relay', 'anywhere', 'Running relay · Cubs', 'Sixes · hall or field', '[{"type":"verse","text":"Each lap adds one more runner, until the whole Six is running hand in hand."},{"type":"steps","heading":"How to play","items":["Mark a line some distance away (line AB). The Six lines up at the start.","The first Cub runs over the line AB and back, then takes the hand of the second Cub. Together they run over line AB and back.","They fetch the third Cub, then run again, and so on, until the whole Six is holding hands in a chain.","When everyone has run, repeat in reverse, with the last Cub starting.","The race ends when the whole Six is back in its original place."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 2),
  ('relay', 'fill-the-bottle', 'Fill the Bottle', 'outdoors', 'Water relay · Cubs', 'Sixes · field', '[{"type":"verse","text":"Carry water in a small cup to fill a bottle at the other end."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Small paper cup per Six"},{"qty":1,"item":"Bucket of water per Six"},{"qty":1,"item":"Empty bottle per Six"}]},{"type":"steps","heading":"How to play","items":["Each Six lines up at one end. At the other end are a bucket of water and an empty bottle.","The first Cub runs to the bucket, fills the cup and runs back to pour it into the bottle, then hands the cup to the next Cub.","The first Six to fill their bottle wins."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 3),
  ('relay', 'balloon-chase', 'Balloon Chase', 'hall', 'Relay · Cubs', 'Sixes · hall', '[{"type":"verse","text":"Keep the balloon in the air with one hand all the way to the bin."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Balloon per Cub"},{"qty":1,"item":"Large bin per Six"}]},{"type":"steps","heading":"How to play","items":["Each Cub in the Six takes a turn.","The Cub must bat their balloon along the hall with one hand only, never letting it touch the floor.","At the far end, tap or place it in the large bin, then run back so the next Cub can go."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 4),
  ('relay', 'cotton-reel-tower', 'Cotton Reel Tower', 'hall', 'Building relay · Cubs', 'Sixes · hall', '[{"type":"verse","text":"Each Cub adds one reel to the Six''s tower, and the first tower standing wins."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"A pile of cotton reels in different shapes and sizes, for each Six"}]},{"type":"steps","heading":"How to play","items":["Each Six lines up at one end. The reels are at the other.","The first Cub runs to the pile, takes one reel, and starts the tower.","Each Cub adds one reel, in turn. If the tower falls, the Six rebuilds it before anyone adds another.","The first Six with a tower standing after everyone has had a turn wins."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 5),
  ('relay', 'bean-bag-relay', 'Bean Bag Relay', 'hall', 'Throwing relay · Cubs', 'Sixes · hall', '[{"type":"verse","text":"Throw bean bags into a hoop and count who gets the most in."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Hoop per Six"},{"qty":null,"item":"Bean bags"}]},{"type":"steps","heading":"How to play","items":["Put a hoop in front of each Six, a few metres away.","Cubs take turns throwing a bean bag at the hoop.","The Six with the most bags in the hoop at the end wins."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 6),
  ('relay', 'forehead-squeeze-relay', 'Forehead Squeeze Relay', 'hall', 'Pairs relay · Cubs', 'Pairs in Sixes · hall', '[{"type":"verse","text":"Carry a ball between two foreheads without using hands."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Ball per Six"}]},{"type":"steps","heading":"How to play","items":["Pair up the Cubs in each Six. The first pair holds the ball between their foreheads.","They walk to a line and back without dropping it. If it drops, they start again.","The next pair does the same, and so on."]},{"type":"note","text":"A traditional Cub game, listed by Pack 568 and by UK Scouts in their traditional Cub games."}]'::jsonb, 7),
  ('relay', 'rescue-mission', 'Rescue Mission', 'outdoors', 'Team race · Cubs', 'Teams of four · field', '[{"type":"verse","text":"Find two \"wounded\" teammates, bandage them and carry them to safety on a stretcher."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Rolls of toilet paper per team"},{"qty":1,"item":"Large beach towel per team, as a stretcher"}]},{"type":"steps","heading":"How to play","items":["Split into teams of four. Two of each team are the \"casualties\" and wait some way off. The other two are rescuers.","On \"Go\", the rescuers run out to the first casualty, wrap them in toilet paper as bandages and put them on the towel.","With a rescuer at each corner of the towel, carry them back to the start line.","Go back out and rescue the second casualty in the same way.","The first team to bring both home safely wins."]},{"type":"safety","heading":"Safety","items":["The casualty lies still on the towel. Carry slowly and put them down gently."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 8),
  ('relay', 'sack-race', 'Sack Race', 'outdoors', 'Hopping relay · Cubs and Scouts', 'Two teams · field', '[{"type":"verse","text":"Hop to the far cone in a sack, then tag the next."},{"type":"kit","heading":"You need","items":[{"qty":3,"item":"Sacks per team"},{"qty":4,"item":"Cones"}]},{"type":"steps","heading":"How to play","items":["Set cones about 6 m apart. Each team splits in half, with half at each cone.","The first player at each end steps into a sack and hops to the other cone.","The next player takes the sack and goes.","When everyone has gone, the team sits down. The first team seated wins."]},{"type":"note","text":"A Belmont Scouts game. Played on Belmont''s Fathers Day night."}]'::jsonb, 9),
  ('relay', 'tunnel-ball', 'Tunnel Ball', 'anywhere', 'Ball relay · Cubs and Scouts', 'Two teams · hall or field', '[{"type":"verse","text":"Roll the ball through the whole team''s legs, then run to the front."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Ball per team"}]},{"type":"steps","heading":"How to play","items":["Each team stands in a line, legs apart, about 5 m from the other team.","The player at the front rolls the ball back between everyone''s legs.","The player at the back picks it up, runs to the front and rolls it again.","Keep going until everyone has been to the front. Then the team sits down. The first seated wins."]},{"type":"note","text":"A Belmont Scouts game. Played on Belmont''s Fathers Day night."}]'::jsonb, 10),
  ('relay', 'egg-and-spoon-race', 'Egg and Spoon Race', 'outdoors', 'Relay · Cubs and Scouts', 'Two teams · field', '[{"type":"verse","text":"Carry a \"egg\" on a spoon round a cone and back."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Spoon per team"},{"qty":1,"item":"Tennis ball per team, as the egg"},{"qty":2,"item":"Cones per team, about 8 m apart"}]},{"type":"steps","heading":"How to play","items":["Each team lines up at the start cone.","The first player walks or runs to the far cone and back, carrying the ball on a spoon, then passes it on.","If the ball falls, pick it up and carry on from where it dropped.","When everyone has gone, the team sits. The first team seated wins."]},{"type":"note","text":"A Belmont Scouts game. Played on Belmont''s Fathers Day night."}]'::jsonb, 11),
  ('relay', 'caterpillar-race', 'Caterpillar Race', 'outdoors', 'Team race · Scouts', 'Patrols · field or hall', '[{"type":"verse","text":"Each patrol forms a human caterpillar and scoots to the finish line, all linked together."},{"type":"steps","heading":"How to play","items":["Mark start and finish lines about 10 m apart. Each patrol sits in a line facing the finish, each Scout with their legs wrapped around the Scout in front.","Arms are the caterpillar''s legs. On \"Go\", push with your arms and move the caterpillar forward.","If the caterpillar breaks apart, reconnect before moving on.","The first whole caterpillar over the finish line wins."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 12),
  ('relay', 'ball-up', 'Ball Up', 'hall', 'Relay · Scouts', 'Patrols (equal numbers) · hall', '[{"type":"verse","text":"Throw the ball to each Scout in turn, then bring everyone back up in order."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Ball per patrol"}]},{"type":"steps","heading":"How to play","items":["Each patrol lines up behind its Patrol Leader, who stands facing them, holding the ball.","The PL throws to the first Scout, who catches it, throws it back and sits down.","The PL repeats with each Scout in turn, until the last Scout is the only one standing.","The last Scout throws back and shouts \"Up!\". The Scout in front stands, catches the next throw, returns it and shouts \"Up!\".","Continue until everyone is standing. The first patrol done wins."]},{"type":"note","text":"A Belmont Scouts game. Shared by Greg."}]'::jsonb, 13),
  ('relay', 'airplane-race', 'Airplane Race', 'anywhere', 'Paper plane relay · Scouts', 'Patrols · hall or field', '[{"type":"verse","text":"Each Scout folds a paper plane, then each flight starts where the last one landed."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Sheet of paper per Scout"}]},{"type":"steps","heading":"How to play","items":["Each Scout folds a paper plane.","Patrols line up at the start line. On \"Go\", the first Scout throws their plane.","The next Scout throws from where the first plane landed, and so on down the line.","The patrol whose planes end up furthest from the start wins."]},{"type":"box","heading":"Variations","items":["Hold a redesign break and race again.","Use it as a relay between patrols."]},{"type":"note","text":"Based on a game at Boy Scout Trail (boyscouttrail.com), kept in Belmont Scouts'' folders."}]'::jsonb, 14),
  ('relay', 'big-bang-relay', 'Big Bang Relay', 'hall', 'Relay · Scouts', 'Patrols · hall', '[{"type":"verse","text":"You can''t start your run until you hear your teammate''s paper bag go bang."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Chair per Scout"},{"qty":1,"item":"Paper bag per Scout"}]},{"type":"safety","heading":"Safety","items":["Warn the hall''s neighbours, and think of anyone who dislikes loud noises."]},{"type":"steps","heading":"How to play","items":["Patrols sit on chairs in single file, each Scout sitting on a paper bag.","On \"Go\", the first Scout runs to the end of the hall, touches the wall, and returns to their chair.","They sit down, blow up their bag, and burst it with a bang.","The bang is the signal for the next Scout to go.","The first patrol to finish wins."]},{"type":"note","text":"A Belmont Scouts game. Shared by Greg."}]'::jsonb, 15),
  ('relay', 'candle-relay', 'Candle Relay', 'outdoors', 'Relay · Scouts', 'Patrols · field', '[{"type":"verse","text":"Carry a lit candle round a course without letting the flame go out."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Candle per patrol, in a jar or holder"},{"qty":1,"item":"Heavy glove per patrol"},{"qty":1,"item":"Box of matches, held by a leader"},{"qty":1,"item":"Bucket of water, close by"}]},{"type":"safety","heading":"Safety","items":["Older Scouts only, and a leader lights every candle.","The Scout carrying the candle wears a glove. Hair and loose clothing are tied back.","Keep the candle low and clear of other players. Put it out in the bucket at the end."]},{"type":"steps","heading":"How to play","items":["Lay out a course around the yard.","A leader lights the candle for the first Scout, who carries it around the course.","If the flame goes out, a Scout runs back to the leader to be relit. The leader keeps the matches.","Pass the candle and glove to the next Scout.","The first patrol to finish the course with everyone having gone wins."]},{"type":"note","text":"A Belmont Scouts game. Shared by Greg. Also played on Belmont''s Games Night in July 2023."}]'::jsonb, 16),
  ('relay', 'secret-message-relay', 'Secret Message Relay', 'outdoors', 'Message relay · Scouts', 'Teams · field', '[{"type":"verse","text":"Pass a message down the line as fast as you can, and as accurately as you can."},{"type":"steps","heading":"How to play","items":["Mark out a course, such as around the building or to a tree and back.","Each team''s Scouts wait out of earshot, at least 15 m from the start line. One Scout from each team is ready on the line.","Each team''s leader goes to the game leader, who whispers a secret message, such as \"Everyone knows it snows when the wind blows\".","On \"Go\", each leader runs to their first teammate at the start line, tells them the message, then steps aside.","That Scout runs the course, passes on the message to the next Scout, and so on. The last Scout runs the course, then tells the game leader.","The first team home, or the one with the most accurate message, wins."]},{"type":"box","heading":"Variations","items":["If teams are uneven, some Scouts run twice."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 17),
  ('relay', 'human-chain-race', 'Human Chain Race', 'outdoors', 'Team race · Scouts', 'Patrols · field', '[{"type":"verse","text":"Link up through your legs and race to the finish."},{"type":"steps","heading":"How to play","items":["Patrols line up one behind the other at the start line.","Each Scout reaches their right hand between their legs and grasps the left hand of the Scout behind.","On \"Go\", the patrol races to the finish line without breaking the chain."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 18),
  ('relay', 'over-and-under-relay', 'Over and Under Relay', 'anywhere', 'Ball relay · Scouts', 'Patrols · hall or field', '[{"type":"verse","text":"Pass the ball back over your head, and then forward through your legs."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Ball per patrol"}]},{"type":"steps","heading":"How to play","items":["The patrol stands in a line. The first Scout holds the ball.","They pass it over their head to the next Scout, who passes it between their legs to the next, and so on, alternating over and under.","When the ball reaches the last Scout, they run to the front and start again.","Keep going until the line is back in its original order."]},{"type":"box","heading":"Variations","items":["Pass everything over, or everything under."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 19),
  ('relay', 'bucket-brigade', 'Bucket Brigade', 'outdoors', 'Water relay · Scouts', 'Patrols · field', '[{"type":"verse","text":"Pass water along a line of cups, and see who moves the most without spilling."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Large buckets per patrol (about 20 L), one filled to a line 2.5 cm from the top, the other empty with a line 4 cm from the top"},{"qty":1,"item":"Plastic cup per Scout (about 500 mL)"}]},{"type":"steps","heading":"How to play","items":["Each patrol lines up in single file, with the Patrol Leader facing the full bucket. The empty bucket is behind the last Scout.","On \"Go\", the PL fills their cup, pours it into the next Scout''s cup, who pours it into the next, and so on.","The last Scout pours the water into the empty bucket.","Keep going until a patrol has emptied the first bucket and filled the second to the 4 cm mark. Spilling too much means a patrol won''t reach it."]},{"type":"note","text":"Based on a patrol game from a Scouts program-resources list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 20),
  ('relay', 'fire-bucket-relay', 'Fire Bucket Relay', 'outdoors', 'Water relay · Scouts', 'Patrols · field', '[{"type":"verse","text":"Carry a nearly full bucket round a cone and pass it back along the line without losing more than a little water."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Bucket per patrol, filled to about 1.5 cm from the top, with a mark 3 cm from the top"},{"qty":1,"item":"Cone or stake per patrol, about 15 m away"}]},{"type":"steps","heading":"How to play","items":["Each patrol lines up in front of its cone. The bucket is at the head of the line.","The first Scout carries the bucket to the cone and back, then hands it to the second Scout, and goes to the back of the line.","The second Scout passes the bucket back down the patrol, Scout to Scout, along one side and up the other, then carries it to the cone.","Continue until each Scout has made a run. In patrols with odd numbers, some go more than once.","The first patrol to complete the number of runs without the water falling below the mark wins."]},{"type":"note","text":"Based on a patrol game from a Scouts program-resources list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 21),
  ('relay', 'shoe-hunt', 'Shoe Hunt', 'outdoors', 'Search relay · Scouts', 'Patrols · field', '[{"type":"verse","text":"Everyone''s shoes go in a big pile. Find your own and be the first patrol back in line."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Circle about 3 m wide marked in the middle, inside a circle about 15 m wide"}]},{"type":"steps","heading":"How to play","items":["Every Scout takes off their shoes and puts them in the middle circle, then goes to the outer circle. Shoes must not be tied together.","A leader mixes the shoes thoroughly.","On \"Go\", everyone races to the middle to find their own shoes, puts them on and laces them, and returns to the outer circle.","The first patrol standing together at attention with all shoes on wins."]},{"type":"note","text":"Based on a patrol game from a Scouts program-resources list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 22),
  ('relay', 'standing-jump-relay', 'Standing Jump Relay', 'outdoors', 'Jumping relay · Scouts', 'Patrols · field', '[{"type":"verse","text":"Each Scout jumps from where the last one landed, and the patrol with the longest total distance wins."},{"type":"steps","heading":"How to play","items":["Patrols line up in relay formation at the start.","The first Scout does a standing broad jump (feet together).","The next Scout jumps from where the first landed, and so on.","If patrols are uneven, some Scouts jump twice.","The patrol that jumps furthest altogether wins."]},{"type":"note","text":"Based on a patrol game from a Scouts program-resources list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 23),
  ('relay', 'tire-roll-relay', 'Tire Roll Relay', 'outdoors', 'Relay · Scouts', 'Patrols · field', '[{"type":"verse","text":"Roll an old tyre through a slalom of cones, and back."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Old tyre per patrol"},{"qty":7,"item":"Cones or stakes per patrol"}]},{"type":"steps","heading":"How to play","items":["Set each patrol''s cones in a straight line, with one more marker at the end.","The first Scout rolls the tyre in and out of the cones, around the end marker, and back through the cones.","The next Scout does the same, and so on, until the tyre has made eight trips. Some Scouts might run twice.","The first patrol to finish eight trips wins."]},{"type":"note","text":"Based on a patrol game from a Scouts program-resources list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 24),
  ('relay', 'wheelbarrow-relay', 'Wheelbarrow Relay', 'anywhere', 'Relay · Scouts', 'Pairs in patrols · hall or field', '[{"type":"verse","text":"One Scout walks on their hands while a partner holds their legs."},{"type":"safety","heading":"Safety","items":["Only on soft ground or mats. Stop for anyone with a sore wrist or shoulder."]},{"type":"steps","heading":"How to play","items":["Mark a start line and a turning line about 6 m away.","Pairs line up in relay formation. The first Scout puts their hands on the ground, and their partner lifts their legs by the ankles.","They travel to the turning line, then swap roles and return, tagging the next pair.","The first patrol to get everyone home wins."]},{"type":"note","text":"Based on a patrol game from a Scouts program-resources list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 25),
  ('wide', 'woods-war', 'Woods War', 'outdoors', 'Field game · Scouts', 'Two teams, 8 or more · large field or bush', '[{"type":"verse","text":"Two gangs of thieves race to bring a treasure back to their own hideout, dodging tennis-ball \"ammo\" on the way."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Treasure chest, or any marker for the treasure"},{"qty":null,"item":"Tennis balls, for ammo"},{"qty":1,"item":"Marker per hideout"},{"qty":null,"item":"A few umpires"}]},{"type":"safety","heading":"Safety","items":["Soft balls only, thrown below the shoulders. No head shots, and no throwing from point-blank range.","Agree boundaries before you start, and check them for holes, stumps and hazards."]},{"type":"steps","heading":"How to play","items":["Mark out a play area at least the size of a football field. Put the treasure in the middle.","Each team has a hideout, a circle about 3 m wide around a marker near the end of their side. It is the only safe place.","A Scout may carry no more than two tennis balls.","A Scout hit by a thrown ball is out at once. To pick up the treasure a Scout must drop all their ammo. A Scout hit while carrying the treasure drops it and is out.","Rounds are short, so play several."]},{"type":"box","heading":"Scoring","items":["The team that gets the treasure back to its hideout scores 4 points.","Every Scout who is hit scores 1 point for the other team."]},{"type":"note","text":"There is only one treasure and no jail. It is similar to Capture the Flag."},{"type":"note","text":"Based on a game at Boy Scout Trail (boyscouttrail.com), kept in Belmont Scouts'' folders."}]'::jsonb, 1),
  ('wide', 'capture-the-flag', 'Capture the Flag', 'outdoors', 'Field game · Scouts', 'Two teams · large field', '[{"type":"verse","text":"Slip into the other team''s side, find the flag and bring it home without getting tagged."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Flag or object per team"},{"qty":null,"item":"Cones or ropes, for the boundary and jails"}]},{"type":"safety","heading":"Safety","items":["Agree boundaries first. Tags are touches only, never tackles."]},{"type":"steps","heading":"How to play","items":["Divide the area into two equal halves with a middle line. Each team has its own side, with a jail in a corner and a flag or object at the back.","A player who steps on the other team''s side can be tagged by anyone on that side, and goes to jail. Guards may stand 1.5 m from the jail.","A free teammate can rescue prisoners by running to the jail and touching up to two. They link arms with the freed players and walk back to their own side. They cannot be tagged while linked.","A player who has picked up the flag and is standing still cannot be tagged. Once they start to run they can be. If tagged, they drop the flag where they were caught and stay there.","The first team to bring the other team''s flag back to its own side wins."]},{"type":"box","heading":"Variations","items":["Use several flags, and give each team a few extras to find."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author. Two versions in Belmont''s folders were combined, one by Josh Drake."}]'::jsonb, 2),
  ('wide', 'peddlers-smugglers-and-police', 'Peddlers, Smugglers and Police', 'outdoors', 'Field game · Scouts', '3 teams of equal size · field', '[{"type":"verse","text":"Smugglers try to get goods to the peddlers past the police, and score is kept with cards and receipts."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Numbered cards, low numbers for starting"},{"qty":null,"item":"Items for smuggling (anything small)"},{"qty":null,"item":"Receipts, one per delivery"},{"qty":null,"item":"A scorekeeper"}]},{"type":"steps","heading":"How to play","items":["Split into three equal teams. The peddlers wait at the far end of the field, the police stand in the middle, and the smugglers start at the near end with a leader.","Each smuggler gets an item and a low-numbered card. They try to reach a peddler and hand over the item, avoiding the police.","The police tag smugglers and show them their card. A tagged smuggler gives up their card, and the police keep every card they capture. Police cannot take receipts.","A smuggler who passes an item to a peddler gets a receipt. Smugglers return to the leader for a new item.","Smugglers with a receipt get a higher-numbered card next time. Smugglers whose item was captured get a lower one.","When time is up, all players return to the leader. The peddlers hand in their items and score points. The police''s captured cards are subtracted from the score.","Write the score down, swap jobs and play again."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 3),
  ('wide', 'dinosaur-game', 'Dinosaur Game', 'outdoors', 'Field game · Cubs', 'The whole pack · large field', '[{"type":"verse","text":"Dinosaurs wander a prehistoric landscape collecting food and water, and the carnivores are hunting."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Green chips (food) and blue chips (water), scattered about the field"},{"qty":null,"item":"Coloured hats: yellow for herbivores, orange for omnivores, red for carnivores"},{"qty":null,"item":"Markers for safe zones"},{"qty":4,"item":"Leaders, one in each corner"}]},{"type":"steps","heading":"How to play","items":["Make hats so everyone can tell the dinosaurs apart. Share the pack into herbivores, omnivores and carnivores.","Scatter the green and blue chips around the field and set out the safe zones.","Herbivores start in one corner and omnivores in another. Carnivores start opposite the herbivores.","Every dinosaur needs 2 green food chips and 1 blue water chip. Keep the chips hidden in one hand.","Herbivores and omnivores may rest in a safe zone. Carnivores may not.","When one dinosaur tags another, both go to a corner leader. Water chips cannot be taken.","An omnivore may take one food chip from a herbivore, but not from a carnivore. A carnivore may take one from a herbivore or an omnivore. If the other dinosaur has no food, the hunter goes hungry.","After a swap, the dinosaur that lost food leaves, and the other counts to 10 before leaving.","A round lasts about 10 minutes."]},{"type":"note","text":"The notes don''t say how a round is won. A good option is to count who has collected 2 food and 1 water at the end. Check with the leaders who run it."},{"type":"note","text":"A Belmont Scouts game. From 2023."}]'::jsonb, 4),
  ('water', 'hole-in-the-bucket', 'Hole in the Bucket', 'outdoors', 'Team challenge · Cubs', '6 to 8 per team · field', '[{"type":"verse","text":"A leaky pipe has to be filled by a team plugging every hole with fingers."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Length of PVC pipe per team, capped at one end and drilled with many holes"},{"qty":1,"item":"Hose, or a jug"},{"qty":1,"item":"Drill, to add holes if needed"},{"qty":1,"item":"Stopwatch"}]},{"type":"safety","heading":"Safety","items":["Check the pipe''s holes are smooth, and that the cut ends have no sharp edges.","A sunny day: sunscreen on, and water to drink."]},{"type":"steps","heading":"How to play","items":["Lay the pipe on level ground with the hose or jug ready.","The team has to work together to fill the pipe with water, sealing the holes with their fingers.","Time each team, and see who can fill and hold the water fastest."]},{"type":"box","heading":"Variations","items":["Fill it from a jug instead of a hose.","Use more or fewer players, depending on the team."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 1),
  ('water', 'water-maze', 'Water Maze', 'outdoors', 'Team challenge · Cubs', '2 or 3 per line, up to 3 lines · field', '[{"type":"verse","text":"Each team ferries water along a rope maze, using jugs that cannot be lifted off the rope."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Competition ropes per team, each held with 4 pegs"},{"qty":3,"item":"Cross ropes per team, with 6 pegs, tied at each peg but loose"},{"qty":3,"item":"Jugs per line, each with a handle, threaded onto the rope (a 3 L plastic milk bottle with the base cut off works well)"},{"qty":2,"item":"Very large water containers at the ends of each line, one filled"},{"qty":1,"item":"Stopwatch"},{"qty":1,"item":"Hose, for filling"}]},{"type":"safety","heading":"Safety","items":["Cut the plastic edges smooth. Check pegs are driven in flush."]},{"type":"steps","heading":"How to play","items":["Peg out the two competition ropes. Peg the cross ropes loosely, so the competition ropes can slide.","Wind each competition rope twice around each of the three cross ropes. That makes the maze.","Thread three jugs onto each competition rope.","Teams of 2 or 3 use the jugs to scoop water from one large container, work it through the maze and pour it into the other.","The team that moves the most water in the time limit wins."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 2),
  ('water', 'pass-the-towel', 'Pass the Towel', 'outdoors', 'Water relay · Cubs', 'Sixes · field', '[{"type":"verse","text":"Soak a towel in one bucket, pass it overhead down the line, and squeeze it into another."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Buckets per Six, one full of water and one empty"},{"qty":1,"item":"Small towel per Six"},{"qty":null,"item":"Dry towels for afterwards"},{"qty":4,"item":"Cones"},{"qty":1,"item":"Stopwatch"}]},{"type":"steps","heading":"How to play","items":["Set up each Six in a line between a full bucket and an empty one.","The first Cub soaks the towel in the full bucket. It is passed along the line, over everyone''s heads, to the last Cub, who squeezes it into the empty bucket.","That Cub runs to the front of the line with the towel and starts again.","If the towel is dropped, or not passed overhead, it goes back to the beginning.","After a set time, the Six that has moved the most water wins. Or, the first to fill the far bucket."]},{"type":"box","heading":"Variations","items":["Pass it over and under, alternately.","Stand an arm''s length apart between the buckets."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known. Pass the Towel and \"Water relay: unders and overs\" were the same game in two files."}]'::jsonb, 3),
  ('water', 'water-cup-relay', 'Water Cup Relay', 'outdoors', 'Water relay · Cubs', 'Up to 12 per team · field', '[{"type":"verse","text":"Carry water in a cup, held above your head, from one container to another."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Paper cup per Cub"},{"qty":2,"item":"Large water containers, one full and one empty"},{"qty":4,"item":"Cones, to mark start and end"},{"qty":1,"item":"Stopwatch"}]},{"type":"steps","heading":"How to play","items":["Each team lines up at the start. The full container is at the start and the empty one is at the other end.","The first Cub dips a cup, holds it above their head, runs to the far container, and tips in the water.","They run back and the next Cub goes.","Keep going until time is up. The team with the most water in the far container wins."]},{"type":"box","heading":"Variations","items":["Drill holes in the cups to make it much harder.","Change the team size or the time limit."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 4),
  ('water', 'water-pipe-relay', 'Water Pipe Relay', 'outdoors', 'Water relay · Cubs', 'Up to 12 per team · field', '[{"type":"verse","text":"Join pool noodles end to end to make a pipe, and move water along it."},{"type":"kit","heading":"You need","items":[{"qty":6,"item":"to 8 × Pool noodles per team"},{"qty":1,"item":"Bucket to catch water at the end"},{"qty":2,"item":"Large containers, one full"},{"qty":1,"item":"Stopwatch"}]},{"type":"steps","heading":"How to play","items":["Teams line up in a row. Each player holds a pool noodle.","Join the noodles end to end to make a long pipe, held with a slight downhill slope.","Pour water into the first noodle. The team tries to channel it along the whole pipe into the bucket at the end.","The team that gets the most water into the bucket in the time limit wins."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 5),
  ('water', 'sponge-relay', 'Sponge Relay', 'outdoors', 'Water relay · Cubs', 'Up to 12 per team · field', '[{"type":"verse","text":"Soak a sponge, run it across to the other bucket and squeeze it out."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Sponge per Cub"},{"qty":2,"item":"Large containers, one full"},{"qty":4,"item":"Cones"},{"qty":1,"item":"Stopwatch"}]},{"type":"steps","heading":"How to play","items":["The team lines up at the start, next to a full container. The empty container is at the far end.","The first Cub soaks a sponge, holds it overhead, runs to the far container and squeezes it out.","Run back and tag the next Cub.","The first team to fill the far container, or move the most water in the time limit, wins."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 6),
  ('water', 'battleships-water', 'Battleships (water)', 'outdoors', 'Water game · Cubs', 'Two Sixes · field', '[{"type":"verse","text":"Teams hide behind a sheet and lob wet sponges to hit the other team''s \"ships\"."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Tarp or large sheet, hung high enough that neither team can see over"},{"qty":null,"item":"Rope, pegs and staves, to hold it up"},{"qty":1,"item":"Bucket of wet sponges per team (use sponges rather than water balloons)"},{"qty":4,"item":"Cones, for boundaries"}]},{"type":"safety","heading":"Safety","items":["Lob gently, never fast and never at heads.","Players lying on the ground stay still and keep their faces turned to the side. A judge watches for hits."]},{"type":"steps","heading":"How to play","items":["Hang the tarp across the middle. One team goes either side.","Some players lie on the ground as the \"ships\". The rest throw wet sponges over the sheet.","A ship that is hit is out, but can then join the throwers.","The team that loses all its ships first loses."]},{"type":"note","text":"The original rules were short and left the details open. Try a trial round first."},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 7),
  ('water', 'knock-them-down-water-pumps', 'Knock Them Down (water pumps)', 'outdoors', 'Water game · Cubs', 'Sixes · field', '[{"type":"verse","text":"Use a water pump to shoot down your Six''s targets."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Water pump or squirt gun per Six"},{"qty":1,"item":"Large container of water, for refilling"},{"qty":null,"item":"Targets, on a table"},{"qty":2,"item":"Cones, to mark the firing line"}]},{"type":"steps","heading":"How to play","items":["Set a row of targets on a table at a distance. Mark the firing line with cones.","Each Six gets its own set of targets to knock down.","Cubs take turns at the firing line, shooting at the targets.","The first Six to knock down all of its targets wins."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 8),
  ('water', 'bottle-launcher', 'Bottle Launcher', 'outdoors', 'Water game · Cubs', 'Sixes · large open field', '[{"type":"verse","text":"Launch a bottle with a water-powered pump, and see whose goes furthest."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Bottle launcher pump per Six"},{"qty":1,"item":"Large container of water, for refilling"},{"qty":2,"item":"Cones or ropes, to mark a safe zone"},{"qty":null,"item":"Plenty of open space"}]},{"type":"safety","heading":"Safety","items":["Everyone stands well back behind the launch line. Nobody walks in front until a leader says it is safe.","Check pumps and bottles before each launch."]},{"type":"steps","heading":"How to play","items":["Mark the launch line and a safe area with cones.","Each Six takes turns to fill a bottle, pump it up and launch.","Measure how far each bottle travels. The further the better."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 9),
  ('water', 'pack-of-chooks', 'Pack of Chooks', 'outdoors', 'Water carrying · Cubs', 'Sixes · field', '[{"type":"verse","text":"Chooks drink by sipping. Carry water in a straw to fill the bucket, one sip at a time."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Buckets per Six, one full and one empty"},{"qty":1,"item":"Straw per Cub (try different widths)"},{"qty":null,"item":"Small cups or containers, if you like"}]},{"type":"steps","heading":"How to play","items":["Put a full bucket at the start. A line of cones a few metres away marks the finish, where the empty bucket (or cup) stands.","Each Cub has a straw. Water can only be carried inside the straw, held with a finger over the top.","Cubs take turns dipping their straw, walking to the other bucket and releasing the water in.","The first team to fill their bucket (or cups) wins."]},{"type":"box","heading":"Variations","items":["Give each Cub several straws, thin and wide. Which ones hold the water? Why?"]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 10),
  ('water', 'balloon-ball-water', 'Balloon Ball (water)', 'outdoors', 'Water game · Scouts', 'Two teams · shallow water', '[{"type":"verse","text":"One team guards a floating balloon and the other tries to pop it."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Balloon"}]},{"type":"safety","heading":"Safety","items":["Only in shallow water and with a supervising adult and any lifesaving gear needed for the venue."]},{"type":"steps","heading":"How to play","items":["Float a balloon in shallow water. One team forms a ring around it.","The other team lines up on the shore and, on signal, attacks the balloon to pop it.","After three minutes, swap roles."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 11),
  ('challenge', 'knots-human-knot', 'Knots (Human Knot)', 'anywhere', 'Untangle · Cubs and Scouts', '8 to 12 per group · hall or field', '[{"type":"verse","text":"Tie everyone into a human knot, then untangle it without letting go."},{"type":"steps","heading":"How to play","items":["The group stands in a circle, shoulder to shoulder, and reaches both hands into the middle.","Each person takes the hand of someone across the circle with their right hand, and a different person''s hand with their left. Nobody should hold hands with someone next to them.","Without letting go, the group untangles itself until it is a single circle again, or two linked circles.","If the group is large, make several smaller circles and race them."]},{"type":"box","heading":"Questions to ask afterwards","items":["Who took charge? Did the leader change?","How did the group decide what to do?"]},{"type":"note","text":"A traditional Cub game, listed by Pack 568 and by UK Scouts in their traditional Cub games. Also listed as \"Human Knot\" in a team-building list in Belmont''s folders."}]'::jsonb, 1),
  ('challenge', 'shrinking-islands', 'Shrinking Islands', 'hall', 'Cooperation · Cubs', 'Sixes · hall', '[{"type":"verse","text":"Everyone in the Six has to fit on an island that gets smaller each round."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Piece of cardboard or newspaper per Six, as the island"},{"qty":1,"item":"Whistle"}]},{"type":"steps","heading":"How to play","items":["Put an island on the floor for each Six. Everyone calls \"Go swimming in the sea!\" and moves about.","When the whistle blows, \"sharks!\" Everyone in the Six has to get on the island.","Each round, fold or cut the island smaller.","The Six must work together to find a way for everyone to fit, with no feet on the floor."]},{"type":"note","text":"A traditional Cub game, listed by Pack 568 and by UK Scouts in their traditional Cub games."}]'::jsonb, 2),
  ('challenge', 'island-hopping', 'Island Hopping', 'outdoors', 'Cooperation · Scouts', 'Patrols · field', '[{"type":"verse","text":"Cross to the finish line using only a sheet of paper for each person, minus one."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Sheets of paper or mats, one per Scout, plus one extra"}]},{"type":"steps","heading":"How to play","items":["Lay the papers out in a line. Every Scout stands on one, with the spare at the back.","Pick up the spare and pass it forward to the front of the line.","The front Scout puts it down, and everyone moves forward one step.","Carry on until all Scouts and all papers are over the finish line."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 3),
  ('challenge', 'electric-fence', 'Electric Fence', 'outdoors', 'Cooperation · Scouts', 'Patrols · field', '[{"type":"verse","text":"Get the whole patrol across a rope \"electric fence\" without touching it."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Rope, tied between two trees"},{"qty":null,"item":"Optional: more rope, to make a web with holes"}]},{"type":"safety","heading":"Safety","items":["Stand spotters on both sides. No diving over the top. Team members must be passed, not thrown."]},{"type":"steps","heading":"How to play","items":["Tie the rope between two trees at about hip height on the tallest person, with space showing beneath. Nobody can step over.","Tell the patrol it''s electric: touching the rope or the air between the rope and the ground means starting again.","The patrol must get everyone over or through, without a touch."]},{"type":"box","heading":"Variations","items":["**Rope web:** make a web of rope between two trees with different sized holes. Each patrol has to pass everyone through the holes, without touching the rope. Patrols rotate to a web made by another patrol."]},{"type":"note","text":"Based on a version credited to Micheline England. Electric Fence is credited to Micheline England in one of the files."}]'::jsonb, 4),
  ('challenge', 'build-it-silent-tower', 'Build It (silent tower)', 'outdoors', 'Planning and building · Scouts', 'Patrols · field', '[{"type":"verse","text":"Plan a tower in two minutes, then build it in three minutes without talking."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"A pile of sticks for each team"},{"qty":1,"item":"Roll of twine per team"}]},{"type":"steps","heading":"How to play","items":["Make a pile of building materials for each team.","Each team has 2 minutes to look at the materials, without touching anything, and decide what to build.","Then 3 minutes to build, in complete silence.","The tallest tower wins."]},{"type":"box","heading":"Questions to ask afterwards","items":["How did you work together without talking?","Did one person take over, or did everyone help?","What would you do differently next time?"]},{"type":"note","text":"Based on a game at Boy Scout Trail (boyscouttrail.com), kept in Belmont Scouts'' folders."}]'::jsonb, 5),
  ('challenge', 'walking-a-frame', 'Walking A-Frame', 'outdoors', 'Pioneering challenge · Scouts', 'A patrol · field', '[{"type":"verse","text":"Build an A-frame, then \"walk\" it across the ground with a Scout standing on the crossbar."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Staves, long ones"},{"qty":1,"item":"Small stave, for the crossbar"},{"qty":7,"item":"Ropes, 4 m each"}]},{"type":"safety","heading":"Safety","items":["Use ropes that run to the ground at all four corners, held by patrol members who stay clear of the frame if it falls.","The Scout on the frame is spotted at all times, and an adult is in charge."]},{"type":"steps","heading":"How to play","items":["Build an A-frame with two square lashings at the ends, a diagonal lashing, and the small stave as a crossbar.","Attach four guy ropes to the frame.","One Scout stands on the horizontal stave. Four Scouts hold the guy ropes to keep the frame steady.","Walk the frame forward, one leg at a time, without the Scout who is standing on it touching the ground."]},{"type":"note","text":"See the Pioneering book for the lashings. This game is a chance to put them to the test."},{"type":"note","text":"A Belmont Scouts game. From October 2025."}]'::jsonb, 6),
  ('challenge', 'marshmallow-challenge', 'Marshmallow Challenge', 'anywhere', 'Design challenge · Scouts', '4 to 6 per team · hall', '[{"type":"verse","text":"Build the tallest free-standing tower you can from spaghetti, tape and string, with a marshmallow on top."},{"type":"kit","heading":"You need","items":[{"qty":20,"item":"Sticks of spaghetti per team"},{"qty":1,"item":"Marshmallow per team"},{"qty":null,"item":"1 m × String per team"},{"qty":null,"item":"1 m × Tape per team"},{"qty":null,"item":"Scissors"},{"qty":null,"item":"A timer, and a measuring tape"}]},{"type":"steps","heading":"How to play","items":["Divide into teams of four to six, each with the same materials.","Set a timer for 12 minutes (the original game uses 18).","Each team builds the tallest free-standing structure it can, and the marshmallow must sit on top.","After the time is up, measure each tower that is standing with the marshmallow on top. The tallest wins."]},{"type":"box","heading":"Questions to ask afterwards","items":["What was the hardest part?","Why is testing small versions so useful?","How did you organise yourselves? Did anyone drift off? What would you do differently?"]},{"type":"note","text":"The Marshmallow Challenge was created by Tom Wujec."}]'::jsonb, 7),
  ('challenge', 'how-many-scouts-on-the-table', 'How Many Scouts on the Table?', 'hall', 'Challenge · Scouts', 'A patrol · hall', '[{"type":"verse","text":"Find out how many Scouts a table resting on balloons can carry."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Sturdy table"},{"qty":20,"item":"Balloons"}]},{"type":"safety","heading":"Safety","items":["Spot everyone getting on and off. Keep a leader beside the table. Clear anything sharp away. Check nobody is allergic to latex.","Stop at the first sign of a wobble."]},{"type":"steps","heading":"How to play","items":["The Scouts blow up the balloons and place them on the floor, close together.","Put the table on top of the balloons.","One Scout at a time climbs on. The Scouts can help each other balance.","Count how many the balloons will carry before one pops."]},{"type":"note","text":"A Belmont Scouts game. From October 2025."}]'::jsonb, 8),
  ('challenge', 'stack-the-cups', 'Stack the Cups', 'hall', 'Teamwork challenge · Scouts', 'Four Scouts per team · hall', '[{"type":"verse","text":"Four Scouts stack six cups into a pyramid without touching the cups with their hands."},{"type":"kit","heading":"You need","items":[{"qty":6,"item":"Plastic cups"},{"qty":1,"item":"Rubber band"},{"qty":4,"item":"Pieces of string"}]},{"type":"steps","heading":"How to play","items":["Tie a piece of string to the rubber band at four points, one for each Scout.","Each Scout pulls on a string to stretch the band wide so it can grip a cup.","Working together, the team picks up each cup and builds a pyramid of 3, then 2, then 1.","Nobody touches the cups with their hands."]},{"type":"note","text":"A Belmont Scouts game. From October 2025."}]'::jsonb, 9),
  ('challenge', 'water-bottle-challenge', 'Water Bottle Challenge', 'anywhere', 'Teamwork challenge · Scouts', 'A patrol · hall or field', '[{"type":"verse","text":"Use rubber bands on strings to lift a bottle out of a danger zone, without anyone entering it."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Bottle, or several"},{"qty":1,"item":"Lid, or a stand to put it on"},{"qty":null,"item":"Several rubber bands, each with strings tied to it"},{"qty":null,"item":"Rope or chalk, to mark the danger zone"}]},{"type":"steps","heading":"How to play","items":["Mark off an area as \"radioactive\". Put the bottle in the middle, with a lid or stand elsewhere.","The team stays outside the zone. They hold the strings and stretch the rubber bands over the bottle.","They lift it out of the zone and set it on the lid. Nobody may step in.","Add a story about radioactive waste to make it more fun."]},{"type":"note","text":"Based on a game from Tyakunda Scout Group, Scouts Queensland."}]'::jsonb, 10),
  ('challenge', 'team-knotting', 'Team Knotting', 'anywhere', 'Knotting challenge · Scouts', 'Teams · hall or field', '[{"type":"verse","text":"Everyone has a rope tied to their wrist. Can the team tie a knot in a rope they can''t let go of?"},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Short ropes, each with a non-tightening loop tied at each end"}]},{"type":"steps","heading":"How to play","items":["Each Scout slips a hand through a loop, as if the rope were tied to their wrist.","Challenge the team to tie a given knot, such as a bowline.","Make it harder by asking for the knot to be in the middle, or a certain number of people from the end.","A harder challenge: tie two trees together with a specific knot. Or: can you tie the whole troop into a truckie''s hitch?"]},{"type":"note","text":"Based on a game from Tyakunda Scout Group, Scouts Queensland."}]'::jsonb, 11),
  ('challenge', 'rope-rescue-lifeline', 'Rope Rescue (Lifeline)', 'anywhere', 'Teamwork and knots · Scouts', 'A patrol · hall or river', '[{"type":"verse","text":"One Scout sits on a tyre at the far end, and the patrol throws them a lifeline and pulls them home."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Lifeline per patrol (a long rope, with a weight on the end if you like)"},{"qty":1,"item":"Old car tyre per patrol"},{"qty":1,"item":"Carpet mat per patrol"}]},{"type":"safety","heading":"Safety","items":["In a hall only, to begin with. If you play it by a river, add life jackets and a rescue plan."]},{"type":"steps","heading":"How to play","items":["Each patrol lines up at one end of the hall, with the Patrol Leader in front and the Assistant PL at the back.","On \"Go\", the PL runs to the far end with the tyre and mat. They lay the mat down, put the tyre on top, and sit on it with arms out.","The second Scout throws the lifeline to land over the PL''s arms, holding on to their end of it.","The PL ties the lifeline around the tyre with a round turn and two half hitches, a bowline or another agreed knot. A leader checks the knot.","When the leader says OK, the patrol pulls the PL back. The back Scout coils the rope as it comes, ready for the next throw.","Untie the knot. The PL goes to the back. The next Scout takes the tyre and mat, and the next throws.","When everyone has done both jobs, the patrol stands to attention with the rope coiled on the tyre on the mat. The fastest wins."]},{"type":"box","heading":"Tips","items":["A very good time is 10 to 15 seconds per Scout.","Use it at the start, middle and end of a Patrol Leaders'' course to see how much each patrol improves."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 12),
  ('challenge', 'paper-fold', 'Paper Fold', 'hall', 'Cooperation · Scouts', '5 or 6 per team · hall', '[{"type":"verse","text":"Everyone stands on one sheet of paper. Fold it, and stand on it again, and again."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Sheet of newspaper or flipchart paper per team"}]},{"type":"steps","heading":"How to play","items":["Teams of five or six stand on their sheet. Shoes can come off if inside.","Everyone steps off. Fold the sheet in half.","Everyone steps back on.","Keep folding. The last team with everyone still on the paper wins."]},{"type":"box","heading":"Variations","items":["Standing on one leg, or other balancing tricks, are allowed and encouraged."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 13),
  ('challenge', 'trust-falls', 'Trust Falls', 'anywhere', 'Trust activity · Scouts', 'Pairs or groups · hall or field', '[{"type":"verse","text":"Fall backwards and let your partner catch you."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Mats, if you can"}]},{"type":"safety","heading":"Safety","items":["Only for older Scouts, with an adult watching every group. The catchers keep a wide stance, with one foot forward and arms ready.","Never let anyone try it on their own. Stop the activity if there is any messing about."]},{"type":"steps","heading":"How to play","items":["One Scout, the faller, stands with their back to a partner. The partner stands close behind them, with arms up and one leg forward.","The faller crosses their arms, keeps their body straight, and falls backwards. The catcher catches them under the shoulders.","Swap places. Try a larger distance only once everyone is confident.","Another version has two Scouts face each other with hands out, and fall towards each other."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 14),
  ('challenge', 'wind-in-the-willows', 'Wind in the Willows', 'anywhere', 'Trust activity · Scouts', 'A circle · hall or field', '[{"type":"verse","text":"A Scout in the middle falls in any direction, and the circle catches them and stands them up."},{"type":"safety","heading":"Safety","items":["Older Scouts only, with an adult watching. Everyone in the circle stands in a strong stance with hands up."]},{"type":"steps","heading":"How to play","items":["The group stands close in a circle, shoulder to shoulder. One Scout stands in the middle with arms crossed and body straight.","The Scout falls slowly in any direction. The circle catches them and gently passes them back upright.","Swap until everyone has had a turn."]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com)."}]'::jsonb, 15),
  ('challenge', 'blind-shapes', 'Blind Shapes', 'hall', 'Communication · Scouts', 'A patrol · hall', '[{"type":"verse","text":"With eyes closed, form a square or triangle using a rope."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Long rope, tied into a loop"},{"qty":null,"item":"Blindfolds, if you like"}]},{"type":"steps","heading":"How to play","items":["Everyone holds the rope, then closes their eyes or puts on a blindfold.","Everyone puts the rope on the floor and walks a few steps away, then walks back.","Without taking blindfolds off, the group must form a shape with the rope, such as a square or a triangle.","To make it harder, tell some Scouts to stay silent."]},{"type":"box","heading":"Questions to ask afterwards","items":["Who led? How did you share ideas?","How did you trust each other?"]},{"type":"note","text":"Based on a game in MacScouter''s Great Games Resource (macscouter.com). Blind Shapes and \"The Perfect Square\" were the same game."}]'::jsonb, 16),
  ('challenge', 'robots', 'Robots', 'anywhere', 'Communication challenge · Scouts', '3 to 5 per team · hall or field', '[{"type":"verse","text":"A blindfolded \"robot\" is guided by two teammates, one who can only see and one who can only talk."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Rope, for the start line"},{"qty":1,"item":"Blindfold per team"},{"qty":1,"item":"\"Bomb\" to fetch, such as a mini football"}]},{"type":"safety","heading":"Safety","items":["A leader watches every robot and stops anyone who steps out of the area."]},{"type":"box","heading":"The three roles","items":["**Robot:** blindfolded, facing the bomb, and the only person allowed in the area.","**Communicator:** faces away from the area and must never look at the robot.","**Observer:** faces the area and watches the robot, but cannot speak at all."]},{"type":"steps","heading":"How to play","items":["Divide into teams of three to five and give each team a role each.","The observer shows the communicator what to say using signs, and the communicator calls instructions to the robot.","The first robot to retrieve the bomb for their team wins.","Rotate roles every three minutes, so everyone gets to be the robot."]},{"type":"box","heading":"Questions to ask afterwards","items":["Did you have a plan, and did you change it?","How did it feel being blindfolded? Did you trust your communicator?","What would you change?"]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known. Three identical copies were in the folders under different names, including \"Tui Game\"."}]'::jsonb, 17),
  ('challenge', 'amoeba-walk', 'Amoeba Walk', 'outdoors', 'Group challenge · Scouts', 'A patrol or two · field', '[{"type":"verse","text":"A patrol forms a living amoeba and moves through a field under the direction of its \"nucleus\"."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Blindfold per cell-wall Scout"}]},{"type":"steps","heading":"How to play","items":["Each amoeba has three parts. The cell wall is made of Scouts who face outward, link elbows and wear blindfolds. They cannot talk.","The protoplasm is a group of Scouts inside the wall, who cannot talk either.","The nucleus sits on the shoulders of a couple of the protoplasm, and is the only one who can speak. They can see.","The amoeba travels out to a marker and back, guided by the nucleus.","Score by time: the shortest out-and-back time wins."]},{"type":"safety","heading":"Safety","items":["Check the route first. Leaders walk beside each amoeba."]},{"type":"note","text":"A Belmont Scouts game. From a team-building night in 2018."}]'::jsonb, 18),
  ('challenge', 'handicap-obstacle-course', 'Handicap Obstacle Course', 'hall', 'Teamwork challenge · Scouts', 'A patrol · hall', '[{"type":"verse","text":"Every Scout gets a limitation by drawing a card, and the patrol must help each other round a course."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Pack of playing cards"},{"qty":null,"item":"Scarves, for tying and blindfolds"},{"qty":1,"item":"Obstacle course, roped off, about 1.2 m wide"}]},{"type":"steps","heading":"How to play","items":["Each Scout draws a card. Clubs means no legs (tie ankles together), spades no arms (hands tied behind), hearts no talking (a loose scarf over the mouth), diamonds no sight (blindfold).","The patrol must get everyone round the track, helping one another.","The shortest time wins."]},{"type":"note","text":"This game uses disability as a theme. Think carefully before you play it, and reword it to be about \"limits\" for a mixed group."},{"type":"note","text":"A Belmont Scouts game. From a team-building night in 2018."}]'::jsonb, 19),
  ('challenge', 'helium-stick', 'Helium Stick', 'anywhere', 'Teamwork challenge · Scouts', 'A patrol · hall or field', '[{"type":"verse","text":"Lower a light pole to the ground, with every finger staying on it."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Light pole, about 2 m long, such as thin plastic tube or bamboo"}]},{"type":"steps","heading":"How to play","items":["Patrols stand in two rows facing each other. Everyone holds out an index finger, held flat and horizontal so the pole can''t sit in a groove.","Lay the pole on everyone''s fingers and adjust until it''s level and every finger touches it.","The challenge is to lower the pole to the ground. Everyone''s finger must stay in contact with it the whole time. No pinching or grabbing.","It is harder than it looks: the pole tends to rise, as everybody pushes up to keep touching.","The fastest to the ground wins."]},{"type":"note","text":"A Belmont Scouts game. From a team-building night in 2018."}]'::jsonb, 20),
  ('challenge', 'zulu-toss', 'Zulu Toss', 'anywhere', 'Teamwork challenge · Scouts', 'A patrol in a circle · hall or field', '[{"type":"verse","text":"Pass a ball around a circle in a set order. Then add another, and another."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Tennis ball or light ball per Scout"}]},{"type":"steps","heading":"How to play","items":["The patrol stands in a circle. One Scout tosses a ball to someone across the circle, who tosses it to somebody else, and so on, until everyone has caught it once. The last Scout tosses back to the first.","Repeat until everyone knows who they receive from and who they throw to.","Start the ball again. When it is half-way round, add a second ball. Keep adding balls.","The longest time with no drops wins."]},{"type":"note","text":"A Belmont Scouts game. From a team-building night in 2018."}]'::jsonb, 21),
  ('challenge', 'key-grab', 'Key Grab', 'hall', 'Silent communication · Scouts', 'Two patrols · hall', '[{"type":"verse","text":"A silent hand-squeeze race to grab the keys, but only if a coin lands heads."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Set of keys"},{"qty":1,"item":"Coin"},{"qty":1,"item":"Chair per Scout, and 1 for the keys"}]},{"type":"steps","heading":"How to play","items":["Put the keys on a chair at one end. Line two rows of chairs back to back leading away from the keys, with one patrol in each row, sitting and holding hands with their neighbours.","The Scout next to the keys is ready to grab. The Scout at the far end watches a leader who is holding the coin.","Nobody speaks. If they do, their patrol loses the round.","The leader tosses the coin. On heads, the far Scout squeezes the hand beside them, and the squeeze is passed along the row to the Scout at the keys, who grabs. First to grab wins.","On tails, nobody should grab. A patrol that grabs on tails loses the round.","Play first to a set number of wins."]},{"type":"note","text":"A Belmont Scouts game."}]'::jsonb, 22),
  ('challenge', 'the-tail-wagging-the-blind-dog', 'The Tail Wagging the Blind Dog', 'outdoors', 'Teamwork challenge · Scouts', 'A patrol · field', '[{"type":"verse","text":"The patrol is blindfolded and linked on a rope, and only the Patrol Leader at the back can see."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Rope per patrol, or a long lashing"},{"qty":null,"item":"Blindfolds, for everyone except the PL"},{"qty":null,"item":"A course through trees, round flagpoles and so on"}]},{"type":"safety","heading":"Safety","items":["Check the course. A leader walks beside the patrol and stops them if there is a hazard."]},{"type":"steps","heading":"How to play","items":["The patrol holds a rope about 1 m apart. Everyone is blindfolded except the PL, who is at the back. The APL is at the front.","A leader directs the PL on the course with signals.","The PL calls instructions to the patrol, who must follow them, with most going to the APL at the front. Using names helps.","Set one or two courses up beforehand and time them."]},{"type":"note","text":"A Belmont Scouts game."}]'::jsonb, 23),
  ('challenge', 'nitro-transport', 'Nitro Transport', 'outdoors', 'Teamwork challenge · Scouts', 'A patrol · field', '[{"type":"verse","text":"Carry a can of \"radioactive nitro\" on a board held with cords, without spilling."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Tin can, 500 mL, filled with water to 6 mm from the top"},{"qty":1,"item":"Board, 30 cm square, with a 1.8 m cord tied through each corner"},{"qty":1,"item":"Marker, for the fill line"}]},{"type":"steps","heading":"How to play","items":["Mark point A and point B about 8 to 9 m apart.","The patrol stands around the board holding the cords. They must lift the can on the board and move it from A to B without spilling any water.","If water spills, start again.","Run it as a relay, or as a challenge to get the best time with the least water lost."]},{"type":"box","heading":"Variations","items":["Use a bigger can filled to 1.2 cm from the top."]},{"type":"note","text":"Based on a patrol game from a Scouts program-resources list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 24),
  ('challenge', 'toxic-waste', 'Toxic Waste', 'outdoors', 'Problem solving · Scouts', '8 to 15 · field', '[{"type":"verse","text":"Empty a bucket of \"toxic waste\" into a far bucket without anyone entering the danger zone."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Rope, to make a circle at least 2.5 m across"},{"qty":1,"item":"Small bucket, filled with water or balls"},{"qty":1,"item":"Large bucket, 10 to 15 m away"},{"qty":1,"item":"Bungee loop"},{"qty":1,"item":"Cord per player"},{"qty":null,"item":"Optional: extra \"red herring\" objects"}]},{"type":"steps","heading":"How to play","items":["Lay the rope in a circle on the ground. Put the small bucket in the middle. Put the large bucket well away. Pile the other equipment nearby.","The group has to move the waste to the large bucket using only the equipment, and without anyone entering the circle.","Allow 5 minutes to plan, then 15 to 20 to carry it out.","If someone steps inside the circle, they lose a limb or a sense for the rest of the game, for example a hand behind the back or a blindfold. If a whole person steps in, they sit out.","If the waste spills completely, talk about what went wrong, refill and try again."]},{"type":"box","heading":"Tips","items":["A bungee loop with cords tied on can grip the bucket from a distance, and the whole group can lift it together.","Make it harder by increasing the circle, the distance, or adding obstacles."]},{"type":"note","text":"Based on an activity at Wilderdom (wilderdom.com)."}]'::jsonb, 25),
  ('challenge', 'all-aboard', 'All Aboard', 'anywhere', 'Cooperation · Scouts', 'A patrol · hall or field', '[{"type":"verse","text":"Everyone must fit on a tarp that keeps getting smaller."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Tarp, blanket or circle of rope"}]},{"type":"safety","heading":"Safety","items":["Check everyone is comfortable with close contact. Take off watches and dangling jewellery."]},{"type":"steps","heading":"How to play","items":["The whole group fits on the tarp.","Fold the tarp to make it smaller, and try again. How small can you go?"]},{"type":"box","heading":"Variations","items":["**Tarp flip:** get everyone standing on the tarp, and turn the tarp over without anyone touching the ground.","**Names:** everyone must use the name of the person they talk to."]},{"type":"note","text":"Based on an activity at Wilderdom (wilderdom.com)."}]'::jsonb, 26),
  ('challenge', 'birthday-line-up', 'Birthday Line-up', 'anywhere', 'Silent communication · Scouts', 'A patrol · anywhere', '[{"type":"verse","text":"Line up in order of birthday, without saying a word."},{"type":"steps","heading":"How to play","items":["Ask the patrol to line up in order of their birthdays, by month and day. Skip the year.","Nobody may talk. Expect signs, nudges and someone to take charge."]},{"type":"note","text":"A Belmont Scouts game. From Games Night, July 2023."}]'::jsonb, 27),
  ('challenge', 'loop-de-loop', 'Loop-de-loop', 'hall', 'Circle challenge · Scouts', 'A circle · hall', '[{"type":"verse","text":"Pass a hula hoop all the way around a circle without anyone letting go of hands."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Hula hoop to begin, then more"}]},{"type":"steps","heading":"How to play","items":["The group stands in a circle, holding hands.","Hang a hoop over one pair of joined hands.","Every person passes the hoop over their body and on to the next person, without letting go.","Add more hoops, going in different directions."]},{"type":"note","text":"A Belmont Scouts game."}]'::jsonb, 28),
  ('challenge', 'aerial-explosives', 'Aerial Explosives', 'hall', 'Teamwork challenge · Scouts', 'Patrols · hall', '[{"type":"verse","text":"Burst a balloon on the ceiling without standing up, using only the equipment you have."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Balloon, fixed to the ceiling, per patrol"},{"qty":null,"item":"Staves, rope and twine"},{"qty":1,"item":"Candle and matches, held by a leader"}]},{"type":"safety","heading":"Safety","items":["This uses naked flame. A leader lights and holds the candle, and only older Scouts should play. Keep the balloon well away from anyone''s head and hair.","If you can''t do that safely, leave the candle out and use a pin on a stave."]},{"type":"steps","heading":"How to play","items":["Pin an inflated balloon to the ceiling in the middle of each patrol''s area.","Each patrol sits on the floor beneath its balloon with its equipment.","The patrol must burst the balloon without anyone standing up.","The first patrol to burst their balloon wins."]},{"type":"note","text":"A Belmont Scouts game. Shared by Greg."}]'::jsonb, 29),
  ('challenge', 'lava-river-crossing', 'Lava River Crossing', 'anywhere', 'Cooperation · Scouts', 'A patrol · hall or field', '[{"type":"verse","text":"Get everyone across the \"lava\" using a limited set of blocks."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"A set of blocks or mats per patrol"}]},{"type":"safety","heading":"Safety","items":["Do it only on a flat, clear space. No real lava."]},{"type":"steps","heading":"How to play","items":["Mark out a river of lava between two lines.","Give each patrol a limited set of blocks, fewer than the number of Scouts, to lay a path across.","Everyone must cross without touching the lava."]},{"type":"note","text":"The original notes were brief. Try it and adjust the rules."},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 30),
  ('challenge', 'circle-link', 'Circle Link', 'anywhere', 'Cooperation · Scouts', 'A patrol · hall or field', '[{"type":"verse","text":"Sit in a circle, linked by the arms, and stand up together."},{"type":"steps","heading":"How to play","items":["The patrol sits in a circle with legs crossed and arms linked.","On the signal, everyone tries to stand up without breaking the circle."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 31),
  ('challenge', 'read-it-do-it', 'Read It, Do It', 'outdoors', 'Signalling · Scouts', 'A patrol · field', '[{"type":"verse","text":"Send a signal to a teammate across the field, and watch them do what it says."},{"type":"steps","heading":"How to play","items":["Split each patrol into senders and receivers, standing at least 20 m apart. The PL chooses a way to signal, such as semaphore or flags.","The first sender signals a task to the first receiver, such as \"salute\" or \"tie a knot\".","The receiver must do it. Then the next pair goes.","Keep going until every patrol member has sent and received once."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 32),
  ('challenge', 'sealed-orders', 'Sealed Orders', 'hall', 'Communication · Scouts', 'Two groups · hall', '[{"type":"verse","text":"Two teams get conflicting secret orders, and have to work out what to do."},{"type":"steps","heading":"How to play","items":["Split the troop into two groups. Each sends a representative to a leader to get written orders.","The representative takes them back and reads them to the team.","On \"Go\", the teams try to carry out their orders.","Give orders that clash, for example one team has to leave the room while the other must not let anyone leave.","Talk afterwards about how each team handled it."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 33),
  ('challenge', 'ships-in-the-fog', 'Ships in the Fog', 'hall', 'Communication · Scouts', 'Patrols · hall', '[{"type":"verse","text":"A blindfolded patrol is steered into harbour by its Patrol Leader''s voice."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Blindfolds"},{"qty":2,"item":"Chairs, to make the mouth of the harbour"}]},{"type":"safety","heading":"Safety","items":["Leaders walk alongside, and chairs can be swapped for cones."]},{"type":"steps","heading":"How to play","items":["The PL stands inside the \"harbour\", marked by two chairs. The rest of the patrol stands blindfolded in single file, with hands on the shoulders of the person ahead.","The PL shouts directions so the ship (the patrol) reaches the harbour.","The first patrol into harbour wins."]},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 34),
  ('challenge', 'triangulate-your-place', 'Triangulate Your Place', 'anywhere', 'Memory challenge · Scouts', '6 to 12 · hall', '[{"type":"verse","text":"Remember where you stand, then rebuild a triangle around someone who has turned."},{"type":"steps","heading":"How to play","items":["All but one stand in a triangle, facing in. The remaining player stands in the middle and faces any direction.","Everyone notices where they are in relation to the middle player and their neighbours.","The middle player slowly spins, then stops without warning, facing a new direction.","The group has a set time to rebuild the triangle so it matches the new direction."]},{"type":"note","text":"The original notes were hard to follow. Try it in a short round, and adjust the rules."},{"type":"note","text":"From a team-building games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 35),
  ('challenge', 'the-mine-field', 'The Mine Field', 'outdoors', 'Trust · Scouts', 'Pairs · field', '[{"type":"verse","text":"A blindfolded Scout is guided through a field of obstacles by a partner''s voice."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Cones, balls and bottles, scattered over the area"},{"qty":1,"item":"Blindfold per pair"}]},{"type":"safety","heading":"Safety","items":["Check the space for holes and hazards, and remove them first. Leaders watch for anyone heading for trouble."]},{"type":"steps","heading":"How to play","items":["Scatter obstacles over an open space.","Pair up. One of each pair is blindfolded and cannot speak. The other guides them across with words only.","Anyone touching an obstacle starts again.","To make it harder, mark a specific route."]},{"type":"note","text":"From a team-building games list kept in Belmont Scouts'' folders; the original author is not known."}]'::jsonb, 36),
  ('skills', 'two-cub-reef-knots', 'Two-Cub Reef Knots', 'anywhere', 'Knotting · Cubs', 'Pairs · anywhere', '[{"type":"verse","text":"A reef knot tied by two Cubs who have only one hand each."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Rope per pair"}]},{"type":"steps","heading":"How to play","items":["Pair the Cubs. One Cub may use only their left hand and the other only their right.","Together, they tie a reef knot in the rope.","Pairs who finish can swap hands and try again."]},{"type":"box","heading":"Questions to ask afterwards","items":["What did you have to do to get it done?","How might this feel for someone who has the use of only one hand?"]},{"type":"note","text":"A good game to talk about working together, cooperation and including everyone."},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 1),
  ('skills', 'phonetic-alphabet', 'Phonetic Alphabet', 'anywhere', 'Word game · Cubs', 'Any number · anywhere', '[{"type":"verse","text":"Learn the phonetic alphabet by saying your name in it, then play hangman with it."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"Paper and pencils"}]},{"type":"box","heading":"The phonetic alphabet","items":["Alfa, Bravo, Charlie, Delta, Echo, Foxtrot, Golf, Hotel, India","Juliett, Kilo, Lima, Mike, November, Oscar, Papa, Quebec, Romeo","Sierra, Tango, Uniform, Victor, Whiskey, X-ray, Yankee, Zulu"]},{"type":"steps","heading":"How to play","items":["Teach the Cubs the phonetic alphabet, and say it through together a few times.","Each Cub writes their name down and then says it using the phonetic words, letter by letter.","Play hangman, but use the phonetic word for each letter guessed."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 2),
  ('skills', 'compass-points', 'Compass Points', 'hall', 'Compass game · Cubs', 'Pack · hall', '[{"type":"verse","text":"Run to the compass point the leader calls, first by Six and colour, then quicker and quicker."},{"type":"steps","heading":"How to play","items":["The pack stands in a circle (or splits in two if there are many). A leader stands at north.","Call a point of the compass. Everyone runs to that point on the circle.","For a listening challenge, call a Six colour first, then a point: \"Red Six, north-west\", \"Yellow Six, south-south-east\". Only that Six runs.","Call faster as the numbers of those still playing go down. Spotters pick out anyone who gets it wrong.","Play to find the fastest reactions."]},{"type":"box","heading":"Tips","items":["Older Cubs make good callers.","A caller can point as well as call, but not necessarily in the right direction."]},{"type":"note","text":"From Belmont Scouts'' games folders; the original author is not known."}]'::jsonb, 3),
  ('skills', 'compass-card-game', 'Compass Card Game', 'outdoors', 'Compass game · Cubs', 'Pack · hall or field', '[{"type":"verse","text":"Draw a card with a compass point on it and run to that direction, then check yourself against the others."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Set of cards: N, NE, E, SE, S, SW, W, NW"},{"qty":2,"item":"Buckets: one for cards, one for discards"},{"qty":4,"item":"or 8 × Cones"},{"qty":1,"item":"Compass per Six"}]},{"type":"steps","heading":"How to play","items":["Put all the cards in one bucket. Mark the points of the compass with cones.","Each Cub draws a card and runs to that direction, either all at once on \"Go\" or one at a time.","When all the Cubs are at a compass point, compare to check whether everyone is correct.","Put the cards in the discard bucket and play again."]},{"type":"box","heading":"Levels","items":["**Silver:** four cones for north, south, east and west.","**Gold:** eight cones for all eight points. Tell the Cubs only where north is, and let them check with a compass."]},{"type":"note","text":"A Belmont Scouts game."}]'::jsonb, 4),
  ('skills', 'morse-code-game', 'Morse Code Game', 'anywhere', 'Signalling · Cubs', 'Groups of four · hall or outdoors', '[{"type":"verse","text":"Send words in Morse code across the room with a torch and decode what the other pair sends."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Torch per group"},{"qty":null,"item":"Game sheets with the words to send, and the Morse alphabet"},{"qty":null,"item":"Pencils"}]},{"type":"steps","heading":"How to play","items":["Make groups of four, in two pairs (1 and 2, 3 and 4), standing well apart, one pair at each end.","Keep the torch on. Send a signal by holding your hand across the front of the torch and taking it away: a short flash is a dot (count 1), a long flash is a dash (count 3).","Leave your hand across the torch for longer between letters (count about 5).","Cub 1 holds the torch and Cub 2 reads out the dots and dashes for each letter. At the other end, Cub 3 reads the torch flashes aloud and Cub 4 writes them down.","Carry on until the sheet is full, then decode the dots and dashes into letters to find the word.","After the first word, the pairs swap ends. Then swap roles within each pair, and send a second word."]},{"type":"box","heading":"The history","items":["Morse code was used in the early days of electric communication, on telegraph wires, before voices could be sent.","It was also sent by radio, and used a lot in the Second World War because it works over long distances.","Navy ships still use it, with powerful lamps, to talk to each other without being seen by others."]},{"type":"note","text":"A Belmont Scouts game."}]'::jsonb, 5),
  ('skills', 'crack-the-code', 'Crack the Code', 'hall', 'Code game · Cubs', 'Sixes · den', '[{"type":"verse","text":"Decode a message in which every letter has been swapped for a number."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Code sheet per Cub: a message written in numbers, with one number for each letter"},{"qty":1,"item":"Pen per Cub"},{"qty":2,"item":"Tables and chairs"}]},{"type":"steps","heading":"How to play","items":["Make the code sheet. Give each letter of the alphabet its own number (use a random two-digit number), then write a line from the Law of the Jungle in numbers, word by word, leaving a space between words.","Give each Six a copy. They work as a team to find the words, looking for repeated numbers.","A good place to start is short words that keep appearing, such as THE or OF.","The first Six to decode the whole message wins."]},{"type":"box","heading":"Tips","items":["The classic Cub message is: \"For the strength of the Pack is the Wolf, and the strength of the Wolf is the Pack.\""]},{"type":"note","text":"A Belmont Scouts game."}]'::jsonb, 6),
  ('skills', 'clove-hitch-around-a-tree', 'Clove Hitch Around a Tree', 'outdoors', 'Knotting race · Scouts', 'Pairs or patrols · field', '[{"type":"verse","text":"Two Scouts hold a rope, and without letting it go, tie a clove hitch around a tree."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Rope, about 3 m, per pair"},{"qty":1,"item":"Tree per pair that you can walk around"}]},{"type":"steps","heading":"How to play","items":["Pairs hold one end of the rope each.","On \"Go\", they tie a clove hitch around the tree without letting go and without passing the rope from hand to hand.","A leader checks the knot. Untie it and play again.","In a patrol with an even number, the next pair takes over the rope when the first pair finishes."]},{"type":"note","text":"A Belmont Scouts game. From Games Night, July 2023."}]'::jsonb, 7),
  ('skills', 'ladder-relay', 'Ladder Relay', 'outdoors', 'Pioneering relay · Scouts', 'A patrol · field', '[{"type":"verse","text":"Lash a ladder together one rung at a time, then climb it."},{"type":"kit","heading":"You need","items":[{"qty":2,"item":"Long poles, for the sides of the ladder"},{"qty":null,"item":"Several short poles, for rungs"},{"qty":null,"item":"Lashing rope"}]},{"type":"safety","heading":"Safety","items":["Test the ladder before anyone climbs. A strong ladder, an adult spotter, and only a short climb."]},{"type":"steps","heading":"How to play","items":["The first Scout runs to the ladder and lashes one end of a rung onto a side pole, then runs back to tag the next Scout.","The next Scout lashes the other end of the rung, and so on.","When the ladder is finished, everyone runs out and holds it steady, and one Scout climbs."]},{"type":"note","text":"See the Pioneering book for the lashings."},{"type":"note","text":"A well-known Scout game. The version in Belmont Scouts'' folders gives no author."}]'::jsonb, 8),
  ('drama', 'how-to-play-theatresports', 'How to Play Theatresports', 'hall', 'Improvisation · Scouts', 'A patrol or troop · hall', '[{"type":"verse","text":"The rules and vocabulary of improvised drama, so scenes work well and everybody has fun."},{"type":"kit","heading":"You need","items":[{"qty":null,"item":"A clear space to perform"},{"qty":null,"item":"A leader as \"compere\", who calls the games"}]},{"type":"steps","heading":"How to play","items":["Split into teams or small groups. The compere sets up a game and gives the players a situation.","Players act it out on the spot, with no script.","Use the ideas below to make scenes work."]},{"type":"box","heading":"Agree to these","items":["Say yes to your partner''s ideas and build on them.","Don''t block, ignore or deny what other actors offer.","Don''t go for cheap laughs.","Be active. Do things, rather than asking questions.","Listen, and stay focused and enthusiastic.","If a scene goes nowhere, change its direction."]},{"type":"box","heading":"Words to know","items":["**Offer:** anything you say or do that gives another actor something to work with.","**Accepting:** taking up an offer and moving the scene forward. \"Is that your car?\" \"Yes! Want to see how fast it goes?\"","**Taking risks:** making a bold choice, like opening an imaginary car door and revving up while others make engine noises.","**Blocking:** refusing an offer, which kills the scene. \"Is that your car?\" \"No, there''s no car here.\" Avoid it.","**Gagging:** going for a laugh that doesn''t help the scene.","**Wimping:** stalling in a way that doesn''t move the scene along."]},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 1),
  ('drama', 'emotion-game', 'Emotion Game', 'hall', 'Improvisation · Scouts', 'Two players · hall', '[{"type":"verse","text":"Two players act out a task, and each time the compere shouts \"Freeze!\", they pick up a new emotion."},{"type":"steps","heading":"How to play","items":["Give two players a situation and a task to do together, such as washing a car.","They set the scene and start the task.","Every 30 seconds or so, the compere shouts \"Freeze!\". The players freeze, and the compere (or the audience) calls an emotion.","The players carry on, acting out that emotion."]},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 2),
  ('drama', 'foreign-film', 'Foreign Film', 'hall', 'Improvisation · Scouts', 'Four players · hall', '[{"type":"verse","text":"Two actors speak gibberish while two translators put it into English."},{"type":"steps","heading":"How to play","items":["Two players act out a story in made-up gibberish. Two others stand to the side as translators.","The translators say what the actors are \"really\" saying in English.","The actors can give the translators ideas, and the translators can steer the actors.","Build the story together."]},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 3),
  ('drama', 'freeze-tag-drama', 'Freeze Tag (drama)', 'hall', 'Improvisation · Scouts', 'A group · hall', '[{"type":"verse","text":"When a scene freezes, a new player taps out an actor and starts a brand new scene."},{"type":"steps","heading":"How to play","items":["Two players begin a scene on a given situation and relationship, such as washing a car. They work with interesting shapes and positions.","Another player calls \"Freeze!\" at a good moment. Both actors freeze.","The caller taps out one actor, takes their exact pose, and starts a new scene from that picture.","Carry on for several minutes so everyone gets turns."]},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 4),
  ('drama', 'park-bench', 'Park Bench', 'hall', 'Improvisation · Scouts', 'A group · hall', '[{"type":"verse","text":"One person sits on a bench with no character. The next person who arrives decides who they both are."},{"type":"kit","heading":"You need","items":[{"qty":1,"item":"Bench or a pair of chairs"}]},{"type":"steps","heading":"How to play","items":["One player sits on the bench in a park, with no character yet.","A second player arrives, decides who they are and who the person on the bench is, for example \"You are a famous sports star, and I''m your biggest fan\".","The player on the bench goes along with it, making the character up as they go.","The scene ends when the first player finds a good reason to leave, such as \"My limo has arrived\".","The second player stays and keeps their character until a third player joins to start a new scene."]},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 5),
  ('drama', 'scene-replay', 'Scene Replay', 'hall', 'Improvisation · Scouts', 'Two players and an audience · hall', '[{"type":"verse","text":"Two players perform a short scene, then do it again in a different way."},{"type":"steps","heading":"How to play","items":["Two players perform a short scene, limited if you like to eight lines each.","The audience suggests a new way to replay it: with a certain emotion, in a different era (through the ages), in a new place, in a particular genre, or backwards.","Replay the scene each time, and see what happens."]},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 6),
  ('drama', 'space-jump', 'Space Jump', 'hall', 'Improvisation · Scouts', 'A group · hall', '[{"type":"verse","text":"Scenes build one by one, adding a player each time, then unwind in reverse."},{"type":"steps","heading":"How to play","items":["The first scene has one player, who may be given a starting situation.","The next player calls \"Freeze!\", steps in, makes sense of the frozen positions, and starts a new scene with two players.","Keep adding players, with each new scene starting from the frozen picture, until everybody is on stage.","Players then leave in reverse order. As each leaves, the earlier scenes continue, and the players justify their new positions as time has passed."]},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 7),
  ('drama', 'story-in-a-minute', 'Story in a Minute', 'hall', 'Improvisation · Scouts', 'Groups · hall', '[{"type":"verse","text":"Act out a whole well-known story in under a minute."},{"type":"steps","heading":"How to play","items":["Give each group a well-known fairytale, story or movie.","They have a minute to perform it, with a beginning, middle and end and all the main characters.","They can act all the parts, use a narrator, or both."]},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 8),
  ('drama', 'typewriter', 'Typewriter', 'hall', 'Improvisation · Scouts', 'A group · hall', '[{"type":"verse","text":"One player types a story out loud, and others join in as the characters arrive."},{"type":"steps","heading":"How to play","items":["One player sits to the side and pretends to type, telling a story out loud as they type.","As characters appear in the story, other players join in and play them.","Characters can add their own dialogue to the story.","Typing noises help."]},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 9),
  ('drama', 'theatresports-ideas', 'Theatresports Ideas', 'hall', 'Prompts · Scouts', 'A group · hall', '[{"type":"verse","text":"Characters, places, stories and moods to suggest to players, written for Scouts."},{"type":"steps","heading":"How to play","items":["Choose one prompt from each list: who, where, what is going on, and how they feel.","Give them to the players and let the scene begin.","Change any of the prompts after a few seconds to keep it lively."]},{"type":"box","heading":"Characters","items":["A pirate captain","A lost tourist","A sleepy bear","A very polite robot","A superhero with a cold","A chef","A postie","A space explorer","A farmer","A king or queen","A surfer"]},{"type":"box","heading":"Where and what","items":["Putting up a tent","Washing a dog","Making a cake","On a desert island","Searching for treasure","Stuck in a lift","In a haunted house","Opening a present","Climbing a mountain","On a train","Under the sea"]},{"type":"box","heading":"Moods","items":["Excited","Nervous","Proud","Shy","Grumpy","Confused","Bored","Hopeful","Cheeky"]},{"type":"box","heading":"Stories to retell","items":["Cinderella","The Three Little Pigs","The Gingerbread Man","Goldilocks and the Three Bears","Jack and the Beanstalk","The Billy Goats Gruff","The Ugly Duckling","Little Red Riding Hood"]},{"type":"note","text":"These prompts are new, based on the kinds of lists in the Theatresports handout. The original lists included some topics that wouldn''t suit younger Scouts, so these have been chosen with care."},{"type":"note","text":"Theatresports is an improvisation format. This version is from a handout in Belmont Scouts'' folders."}]'::jsonb, 10)
